(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-cross-stage-vis-spec"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-1\">一 · 事故现场：一条被视觉拖住的长尾</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-2\">二 · 它到底解决哪一个具体问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-3\">三 · 适用边界：短视觉上下文、分布接近</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-4\">四 · 它不解决什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-5\">五 · 工程判断：先算容量账，再谈加速比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-6\">六 · 视觉投机解码的失效边界：从一次线上事故说起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-7\">七 · 预填落盘：视觉 KV 的只读化与摘要向量生成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-8\">八 · 草稿提案：视觉条件下的 γ 步自回归</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-9\">九 · 并行验证：一次前向、逐位置比对</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-10\">十 · KV 写入与截断回滚：分页池的一致性维护</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-11\">十一 · 动态 γ 与拒绝率反馈环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-12\">十二 · 容量约束：草稿显存与 batch size 的二选一</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-13\">十三 · 边界条件：视觉条件投机在哪些流上会失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-14\">十四 · 接受长度的逐位置判定：从拒绝采样到首个截断点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-15\">十五 · 加速比公式的逐项拆解与 γ 的最优解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-16\">十六 · 可实现的伪代码：草稿提出与验证循环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-17\">十七 · 视觉 KV 复用带来的零编码验证与注意力稀释</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-18\">十八 · 从公式到容量判断：α 与 γ 的联合标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-19\">十九 · 接受长度的分布尾部与 γ 的自适应边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-20\">二十 · 边界条件：接受率塌陷与显存挤压下的收益蒸发</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-21\">二十一 · 请求形态：短视觉上下文与高文本熵的匹配面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-22\">二十二 · 长度分布：输出长度决定摊薄，视觉长度决定稀释</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-23\">二十三 · 并发与批大小：草稿模型的显存挤占是硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-24\">二十四 · 负载不对时的三种失效形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-25\">二十五 · 配方落地：路由、分桶与 γ 的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-26\">二十六 · 负载配方：短视觉上下文、中高并发、偏问答型请求才是它的舒适区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-27\">二十七 · 硬件档位：按显存与算力切三档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-28\">二十八 · 并行拓扑：草稿与目标的切分方式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-29\">二十九 · 量化方案：草稿与目标的不对称精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-30\">三十 · KV 策略：只读视觉池与可写文本池分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-31\">三十一 · 调度参数：γ 的动态控制与拒绝率阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-32\">三十二 · 可复现配置思路：从约束反推参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-33\">三十三 · 视觉投机解码的部署边界：显存预算、模态漂移与 γ 的失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-34\">三十四 · 显存墙：草稿模型与 batch size 的二选一</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-35\">三十五 · 带宽账：验证前向的算术强度与视觉 KV 的只读复用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-36\">三十六 · 通信面：分离式部署下视觉 KV 的搬运与只读语义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-37\">三十七 · 功耗与热：验证前向的瞬时功率尖峰</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-38\">三十八 · 尾延迟：拒绝截断与动态 γ 的滞后</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-39\">三十九 · 规模上去以后哪里先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-40\">四十 · 规模上去以后，先崩的是显存，不是算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-41\">四十一 · 精度漂移：接受率是分布距离的代理指标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-42\">四十二 · OOM 与显存挤压：草稿模型是容量约束的主项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-43\">四十三 · 批抖动：γ 动态调整与批组成变化的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-44\">四十四 · 路由不均与尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-45\">四十五 · 监控面与回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-46\">四十六 · 失效链的定位：从接受率塌陷到显存挤压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-47\">四十七 · 决策轴：把同族算法压到四个可测量维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-48\">四十八 · 与剪枝/压缩族的对照：削减对象不同，代价位置不同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-49\">四十九 · 与并行/调度族的对照：谁在争 batch size</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-50\">五十 · 与投机族内部的对照：通用投机 vs 自适应投机 vs 跨阶段视觉投机</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-51\">五十一 · 决策表：按负载形态给出选择与适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cross-stage-vis-spec-sec-52\">五十二 · 工程判断：把选型固化成运行时开关而非静态配置</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:569px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 569.2 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"487.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">预填阶段完成ViT编码与跨模态注意力，视觉KV写入分页池并标记为只读</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"487.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">草稿模型读取视觉KV摘要向量与当前文本，自回归提出γ=4–8个候选token</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"487.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">目标模型对候选序列做一次并行前向，逐位置比对草稿分布与目标分布</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"487.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">从首个拒绝位置截断，接受前缀token的KV直接写入，拒绝位置由目标模型重…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"487.2\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">若连续拒绝率超阈值则动态降γ，视觉token的KV在验证中复用不重算</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-cross-stage-vis-spec-sec-1\">一 · 事故现场：一条被视觉拖住的长尾</h3>\n<p>某多模态 agent 在线服务在夜间告警：P99 首 token 之后的解码间隔从常态的十几毫秒跳到接近百毫秒量级，队列里堆积的请求并不是图像编码慢，而是文本侧生成卡住。拆开看，预填阶段早已完成 ViT 编码与跨模态注意力，视觉 token 的 KV 安静地躺在分页池里，随后每一轮解码只吐出一个 token，目标模型必须为这一个 token 做一次完整前向。图像内容在这条路径上是一次性成本，而文本生成是串行成本——当 agent 需要连续输出多段结构化结论时，串行部分被放大成主要矛盾。</p>\n<p>值班工程师的第一反应是启用通用投机解码：挂一个轻量草稿模型，一次提出若干候选，目标模型并行验证。上线后指标反而更难看。原因在于通用草稿模型对图像内容不敏感——它没有把视觉编码器输出作为条件，候选 token 的分布与目标模型在视觉问答上的分布偏离明显，接受率只有 0.5–0.6。用这个接受率代入吞吐增益近似式，收益被迅速吃掉：</p>\n<div class=\"formula\">$$S \\approx \\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)(\\gamma+1)},\\quad \\alpha=\\mathbb{E}\\left[\\min\\left(1,\\frac{p_{\\text{tgt}}}{p_{\\text{draft}}}\\right)\\right]$$</div>\n<p>取 γ=6、α=0.55，分子接近 1，分母被 (1−α)(γ+1) 拉到约 3.85，理论加速比落在 1.2 上下；而草稿模型本身还要占显存、要做自己的前向，端到端很可能净亏。事故的实质不是投机解码失效，而是<strong>草稿与目标之间缺少视觉这一层共享条件</strong>：视觉 token 已经固定、已经算过，却没有被草稿模型用起来。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-2\">二 · 它到底解决哪一个具体问题</h3>\n<p>跨阶段视觉投机解码针对的推理问题是：多模态 agent 服务中，预填阶段的视觉编码已完成且视觉 KV 可复用，解码阶段的自回归逐 token 生成仍是串行瓶颈；通用投机解码的草稿模型对图像内容不敏感，导致视觉问答场景接受率偏低、加速比有限。它把同一 VLM 视觉编码器的输出作为草稿模型的跨模态条件，让草稿在“看过图”的前提下提出候选，从而把接受率从 0.5–0.6 抬到 0.75–0.85，端到端解码吞吐提升 1.8–2.4 倍。</p>\n<p>机制上分三段数据流。预填阶段完成 ViT 编码与跨模态注意力后，视觉 KV 写入分页池并标记为只读——只读标记是关键，它让后续验证阶段可以安全复用而不触发重算。草稿模型读取视觉 KV 摘要向量与当前已生成文本，自回归提出 γ=4–8 个候选 token。目标模型对候选序列做一次并行前向，逐位置比对草稿分布 q_i 与目标分布 p_i，按接受长度</p>\n<div class=\"formula\">$$L_{acc}=\\min\\{i: u_i &gt; p_i/q_i\\}$$</div>\n<p>从首个拒绝位置截断：接受前缀的 KV 直接写入分页池，拒绝位置由目标模型重采样，视觉 token 的 KV 在验证中复用不重算。这条路径把“视觉已算完”这一事实转化为草稿侧的条件信号，验证阶段没有额外视觉编码开销，是它相对通用投机解码的结构性差别。</p>\n<p>代价同样明确。草稿模型额外占用显存，在 NVL72 单卡上必须在 batch size 与草稿模型之间做权衡——这是主要容量约束，不是可以靠调参抹平的。高并发时若草稿模型被换出，投机链路直接失效，退化成逐 token 解码，而此时请求已经按投机路径排过队，抖动比一开始就不开投机更大。吞吐账要按“每卡每秒有效 token”算，而不是按单请求加速比算。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-3\">三 · 适用边界：短视觉上下文、分布接近</h3>\n<p>它的收益有明确边界。适用场景是视觉上下文较短、草稿与目标分布接近的视觉问答与多模态 agent 在线服务：单图、少量视觉 token、问题指向图中具体对象或属性时，草稿模型读到的视觉摘要向量足以把候选分布拉到目标分布附近，γ=4–8 的候选里能连续接受多个。此时验证一次并行前向摊薄了 γ 个 token 的目标模型成本，1.8–2.4 倍的解码吞吐提升才站得住。</p>\n<p>不适用的一面同样清楚。视频或多图长视觉上下文下，草稿模型的注意力被稀释——视觉 KV 摘要向量承载的信息密度随视觉 token 数增长而下降，草稿对当前解码位置的视觉相关性判断变弱，接受率回落到接近通用草稿水平，加速比消失而验证开销仍在。这不是靠加大 γ 能救的：γ 越大，无效并行前向浪费的目标模型算力越多。另一类不适用是草稿与目标分布本就偏离的场景，例如目标模型刚做过领域适配而草稿未同步，视觉条件也拉不回来。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>收益成立</th><th>收益衰减/消失</th></tr></thead><tbody><tr><td>视觉上下文</td><td>单图、短视觉 token 序列</td><td>长视频、多图拼接</td></tr><tr><td>分布匹配</td><td>草稿与目标在视觉问答上接近</td><td>目标侧领域漂移、草稿未同步</td></tr><tr><td>并发与显存</td><td>batch size 留有余量容纳草稿</td><td>草稿被换出、batch 被挤压</td></tr><tr><td>模态</td><td>视觉问答、agent 结构化输出</td><td>纯文本长文生成（无视觉条件可用）</td></tr></tbody></table>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-4\">四 · 它不解决什么</h3>\n<p>第一，它不解决预填阶段的视觉编码成本。ViT 编码与跨模态注意力在预填已完成，本算法只复用其结果，对“图太大、编码太慢”的首 token 延迟没有贡献；那属于视觉 token 缩减与缓存复用的范围，本条目不重复。第二，它不解决显存容量本身。草稿模型占的那块显存是净增的，KV 分页池的容量规划、视觉 KV 的换入换出策略不在它的机制内，它只是把“视觉 KV 只读复用”作为前提。第三，它不解决数值精度层面的吞吐——NVFP4/FP8 的算子选择、tcgen05 与 TMEM 的排布是另一层，投机只改变“一次前向验证几个 token”的调度结构。</p>\n<p>第四，它不解决分布漂移的根因。连续拒绝率超阈值时动态降 γ 只是止损：若降 γ 滞后，分布漂移期间会持续做无效并行前向，浪费目标模型算力，表现为吞吐不降反升的功耗浪费。真正的漂移要靠草稿模型更新或路由策略，投机层只能被动收缩。第五，它不适用于无视觉条件的纯文本长文生成——没有视觉 KV 可作跨模态条件，草稿退化为通用草稿，接受率回到 0.5–0.6 区间，收益不足以抵消草稿显存。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-5\">五 · 工程判断：先算容量账，再谈加速比</h3>\n<p>落地前的第一个判断不是“能加速多少”，而是“这张卡还剩多少显存给草稿”。NVL72 单卡上 batch size 与草稿模型二选一，意味着容量规划要把草稿显存当作硬约束写进 SLO 模型：给定目标并发与每请求 KV 占用，先扣掉草稿模型的常驻部分，再看剩余 batch 能否撑住吞吐目标。若扣完后 batch 掉到无法覆盖到达率，投机的 1.8–2.4 倍单请求加速也补不回并发损失。</p>\n<p>第二个判断是模态路由。按输入模态动态调 γ：单图短上下文用 γ=6–8 吃满接受率，多图或视频帧序列主动降到 γ=4 甚至关闭投机，避免“验证开销仍在、加速比消失”的负收益区间。第三个判断是拒绝率的监控粒度——连续拒绝率阈值要按滑动窗口而非全局均值触发降 γ，否则分布漂移时的滞后会让目标模型持续做无效并行前向。这三条判断共同决定这条算法在具体服务里是正收益还是负收益，而公式给出的加速比只是上限，不是承诺。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-6\">六 · 视觉投机解码的失效边界：从一次线上事故说起</h3>\n<p>某多模态 agent 服务在灰度上线通用投机解码后，线上出现了一类典型事故：图像问答请求的 P99 解码延迟不降反升。根因并不在投机解码本身，而在草稿模型与视觉上下文之间的错配。这类服务中，视觉 token 在预填阶段已经固定，ViT 编码与跨模态注意力完成，视觉 KV 写入分页池并标记为只读；瓶颈完全落在解码阶段逐 token 的串行自回归上。团队引入的通用草稿模型只以已生成文本为条件，对图像内容不敏感，视觉问答上的接受率只有 0.5–0.6。按接受长度公式 $L_{acc} = \\min\\{i : u_i &gt; p_i/q_i\\}$（$p_i$ 为目标分布、$q_i$ 为草稿分布、$u_i$ 为均匀采样），低接受率意味着拒绝位置频繁落在候选序列前段，目标模型仍需做一次并行前向却只提交极少 token；同时草稿模型本身要占用显存与算力。于是每步验证的固定开销摊薄到几乎为零的有效产出上，吞吐增益趋近于 1 以下，而排队时间被拉长。事故的工程教训是明确的：投机解码的收益不是无条件成立的，它取决于草稿分布与目标分布在给定上下文下是否足够接近。</p>\n<p>把这一点写成系统代价，可以更清楚地看到边界在哪里。吞吐增益近似为</p>\n<div class=\"formula\">$$S \\approx \\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)(\\gamma+1)},\\quad \\alpha=\\mathbb{E}\\left[\\min\\left(1,\\frac{p_{\\text{tgt}}}{p_{\\text{draft}}}\\right)\\right]$$</div>\n<p>其中 $\\alpha$ 为接受率、$\\gamma$ 为草稿步数。当 $\\alpha$ 从 0.75–0.85 回落到 0.5–0.6，同一 $\\gamma$ 下的 $S$ 会显著缩水；更关键的是，验证阶段的那一次目标模型并行前向的开销与 $\\gamma$ 基本无关，它不会随接受率下降而变小。也就是说，低接受率场景下系统付出的是“完整验证前向 + 草稿前向”的双份算力，换回的却只是被截断的短前缀。跨阶段视觉投机解码正是针对这一失效点设计的：它把同一 VLM 视觉编码器的输出作为草稿模型的跨模态条件，草稿模型读取视觉 KV 摘要向量与当前文本，自回归提出 γ=4–8 个候选 token，目标模型一次并行前向逐位置比对后从首个拒绝位置截断，接受前缀的 KV 直接写入、拒绝位置由目标模型重采样。视觉 token 的 KV 在验证中复用不重算，因此验证阶段没有额外视觉编码开销，接受率被抬到 0.75–0.85，端到端解码吞吐提升 1.8–2.4 倍。但这份收益有明确的适用边界，它并不解决所有多模态推理的慢。</p>\n<p>它不解决的问题可以列成一张边界表。第一，它不改善预填阶段——ViT 编码与跨模态注意力的成本在预填已完成，本方案只作用于解码；视觉上下文极长时预填本身就是主瓶颈，投机解码无从下手。第二，它不解决长视觉上下文下的注意力稀释：视频或多图输入使草稿模型的注意力被大量视觉 token 摊薄，接受率回落到接近通用草稿水平，加速比消失而验证开销仍在，此时必须按模态动态调 γ，甚至退回非投机路径。第三，它不解决容量约束：草稿模型额外占用显存，在 NVL72 单卡上 batch size 与草稿模型是二选一的关系，高并发时草稿模型被换出会直接导致投机失效，这是比接受率更硬的容量天花板。第四，动态降 γ 的策略本身有滞后风险——连续拒绝率超阈值后才降 γ，若阈值响应慢于分布漂移，系统会在漂移期持续做无效并行前向，白白消耗目标模型算力。因此适用边界应表述为：视觉上下文较短、草稿与目标分布接近的视觉问答与多模态 agent 在线服务；一旦进入长视频、多图或高并发挤压显存的区间，收益衰减甚至为负，工程上应把“是否启用跨阶段视觉投机”做成按模态、按负载、按显存余量的运行时判定，而不是全局默认开启。</p>\n<h3 id=\"alg-cross-stage-vis-spec-sec-7\">七 · 预填落盘：视觉 KV 的只读化与摘要向量生成</h3>\n<p>跨阶段视觉投机解码的第一步不在解码，而在预填。目标 VLM 的 ViT 完成图像编码、跨模态注意力把视觉特征压入语言侧之后，视觉 token 对应的 KV 不再参与后续写入，而是被显式标记为只读并落入分页池。这一步的工程含义是：视觉 KV 在整个请求生命周期内只算一次、只写一次，之后所有草稿步与验证步都从分页池按 block 索引读取，不触发重算。与之并行，系统从这批只读 KV 中抽出一个固定维度的摘要向量（对视觉 KV 做池化或取若干代表位置的投影），作为草稿模型的跨模态条件入口。</p>\n<p>输入是 ViT 输出的视觉特征序列与跨模态注意力权重；输出是分页池中的只读视觉 KV 块加上一个摘要向量。代价集中在预填尾段：摘要向量的抽取是一次轻量归约，相对 ViT 前向可忽略，但它引入一次额外的显存读写——视觉 KV 从计算缓冲区搬到分页池，搬运量与视觉 token 数乘以层数乘以 KV 头维度成正比。在 NVL72 单卡上，长视觉上下文（多图、视频帧序列）会让这次搬运占据可观的 HBM 带宽窗口，且只读标记意味着这部分显存无法被后续 batch 复用，直接压缩了可分配给解码 batch 的容量。具体例子：一个带四张图的 agent 请求，视觉 token 数千量级，其只读 KV 常驻分页池后，同一卡上能容纳的并发解码序列数随之下降——这正是后文容量权衡的根源。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-8\">八 · 草稿提案：视觉条件下的 γ 步自回归</h3>\n<p>草稿模型拿到两样东西：只读视觉 KV 的摘要向量，以及当前已生成的文本 token。它以摘要向量作为跨模态前缀条件，对文本侧做 γ=4–8 步自回归，串行提出 γ 个候选 token 及其草稿分布 q。关键区别在于通用草稿模型只看到文本、对图像内容不敏感，而这里草稿的每一步注意力都被视觉摘要锚定，因此候选分布更贴近目标模型在视觉问答上的条件分布。</p>\n<p>伪代码思路如下：草稿侧维护一个长度 γ 的候选缓冲，第 i 步以「摘要向量 + 已生成文本 + 前 i−1 个候选」为输入，输出第 i 个 token 的分布 q_i 并采样；γ 步结束后把候选序列整体交给验证阶段。输入是摘要向量与文本前缀，输出是 γ 个候选 token 与对应 q_i。代价是 γ 次串行小前向：草稿模型参数量远小于目标模型，单步延迟低，但 γ 步仍是串行，其总延迟构成投机路径的固定开销下限。γ 越大，潜在接受长度越长，但草稿串行时间与草稿显存占用同步上升。工程判断是 γ 应按模态给定：短视觉上下文的视觉问答取上限区间，长视频上下文取靠近下限的值，因为此时草稿注意力被稀释，多提的候选大概率在验证阶段被整段截断，纯属浪费。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-9\">九 · 并行验证：一次前向、逐位置比对</h3>\n<p>目标模型对「文本前缀 + γ 个候选」做一次并行前向，一次算出所有 γ+1 个位置的分布 p。验证按标准投机判据逐位置进行：</p>\n<div class=\"formula\">$$L_{acc} = \\min\\{i : u_i &gt; p_i/q_i\\}$$</div>\n<p>其中 p_i 为目标分布、q_i 为草稿分布、u_i 为均匀采样。从首个拒绝位置截断，接受前缀 token 的 KV 直接写入分页池供后续解码复用，拒绝位置由目标模型自身的分布重采样补上。整个验证阶段视觉 token 的 KV 全程复用、不重算——这是本机制相对「每步重编码视觉」方案的核心节省项。</p>\n<p>输入是候选序列与只读视觉 KV，输出是接受前缀、其 KV 块、以及一个重采样 token。代价结构值得拆开看：目标模型这一次前向的计算量约等于处理 γ+1 个 token 的单次批前向，而非 γ+1 次串行前向，因此验证的算力开销被摊薄；但这次前向的显存带宽开销与 γ 正相关，且验证失败时被截断的候选位置所做的计算全部作废。吞吐增益的近似式为</p>\n<div class=\"formula\">$$S \\approx \\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)(\\gamma+1)}$$</div>\n<p>α 为接受率、γ 为草稿步数。代入视觉问答场景的 α=0.75–0.85 与 γ=4–8，端到端解码吞吐落在 1.8–2.4 倍区间；而通用草稿的 α 仅 0.5–0.6，同一公式下增益明显缩水。这说明本机制的全部收益来自 α 的提升，而非验证结构本身的改变。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-10\">十 · KV 写入与截断回滚：分页池的一致性维护</h3>\n<p>接受前缀的 KV 写入不是简单追加。分页池中每个序列的 KV 按 block 管理，验证阶段目标模型算出的候选 KV 先落在临时缓冲，只有被判据接受的连续前缀才被提交为正式 block，拒绝位置之后的候选 KV 全部丢弃。这一步的输入是验证输出的逐位置 KV 与接受掩码，输出是更新后的序列 KV 长度与重采样 token 的 KV。代价是一次条件性写回：接受长度越长，写回量越大、有效吞吐越高；接受长度短时，临时缓冲的分配与释放成为纯开销。工程上要把临时缓冲做成可复用的 arena，否则高频短接受会在分配器上打出碎片。</p>\n<p>与只读视觉 KV 的关系在此处必须说清：视觉 KV 块被标记只读，意味着验证与写回过程绝不能对其做原地更新，任何跨模态注意力的增量都必须落在文本侧 KV 上。这个约束保证了视觉 KV 可被同一请求的多个解码步、乃至同一图像被多个请求共享时安全复用，但也要求分页池的块表能区分只读块与可写块，块表查询多一次分支判断——在高并发下这是每步都要付的固定成本。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-11\">十一 · 动态 γ 与拒绝率反馈环</h3>\n<p>连续拒绝率超阈值时动态降 γ，是本机制唯一的在线自适应环节。实现上维护一个滑动窗口的接受率估计，当窗口内拒绝比例越过阈值，就把 γ 从当前值下调一档，最低可退到接近纯自回归的保守档；接受率恢复后再缓慢上调。输入是每轮验证的接受长度，输出是下一轮的 γ。代价有两面：降 γ 直接缩短草稿串行时间、降低草稿显存峰值，但吞吐增益公式里的 γ 变小也压低了上限；更隐蔽的代价是滞后——分布漂移（例如 agent 从图像描述切换到多轮推理）时若阈值反应慢，系统会持续做无效的并行前向，目标模型算力被白白消耗，而此时验证开销仍在、收益已失。</p>\n<p>具体例子：视频或多图长视觉上下文下，草稿模型注意力被稀释，接受率回落到接近通用草稿水平，加速比趋近于 1 而验证开销照付。此时正确动作是按模态把 γ 压到下限甚至临时关闭投机路径，把算力还给目标模型的串行解码。阈值设定应绑定模态类型而非全局常数，否则短上下文请求会被长上下文请求的坏统计拖累。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-12\">十二 · 容量约束：草稿显存与 batch size 的二选一</h3>\n<p>把上述步骤放回 NVL72 单卡的资源账本上，最紧的约束不是算力而是显存。草稿模型额外占用一份权重与一份激活/KV 空间，与只读视觉 KV 常驻、目标模型权重、解码 batch 的 KV 池共同争夺 HBM。高并发时若草稿模型被换出，投机路径直接失效，请求退回串行解码——这不是性能退化而是机制失效，且换出/换入的抖动会让延迟分布出现长尾。</p>\n<p>因此部署配方必须把「batch size 与草稿模型」当作显式权衡项：要么牺牲并发度保住草稿常驻，要么在低峰期限流草稿、高峰期按请求类型选择性启用。可行的工程判断是按 SLO 分层——对延迟敏感的视觉问答请求保留草稿常驻并限制其并发上限，对吞吐优先的批量请求走无投机路径。视觉 KV 只读化在这里帮了忙：它不会被反复重写，块表稳定，换出决策可以只针对草稿权重而不动视觉 KV，减少了抖动面。真正需要盯住的指标是「草稿常驻率」与「接受率」的乘积，前者掉下去时后者再高也换不来吞吐。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-13\">十三 · 边界条件：视觉条件投机在哪些流上会失效</h3>\n<p>跨阶段视觉投机的收益并非均匀分布在所有请求上，它依赖一条隐含假设：草稿模型能从视觉 KV 摘要向量中稳定提取与目标模型一致的分布偏移。当视觉上下文长度增长时，这条假设最先崩掉。草稿模型的注意力预算固定，视觉 token 数量上升会稀释其对关键区域的权重，摘要向量趋于退化为“平均图像”表征，草稿分布向通用语言先验回退。此时接受率从 0.75–0.85 回落到接近通用草稿的 0.5–0.6 区间，而目标模型仍需为每个候选序列支付一次并行前向。用接受长度公式刻画，截断点 $L_{acc} = \\min\\{i : u_i &gt; p_i/q_i\\}$ 在 $q_i$ 偏离 $p_i$ 时迅速收缩到 1–2，吞吐增益 $S \\approx \\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)(\\gamma+1)}$ 中 $\\alpha$ 下降直接压低分子，分母的 $\\gamma+1$ 却不变——验证开销照付，收益归零。视频与多图请求因此必须按模态动态调 $\\gamma$，把草稿步数压到 2–3 甚至关闭投机，而不是沿用视觉问答的 4–8。</p>\n<p>显存是第二条硬边界。草稿模型与目标模型共享视觉 KV，验证阶段不重算视觉编码，这部分省下的带宽是方案成立的前提；但草稿模型自身的权重与运行时激活额外占卡。在 NVL72 单卡上，batch size 与草稿模型构成零和：高并发时若把草稿模型换出到主机侧，每次投机都要重新加载权重，跨阶段流水被打断，投机退化为串行解码，延迟反而高于不投机。工程判断是给草稿模型划定常驻显存配额，并把 batch size 的上限按“目标模型 KV + 草稿常驻 + 视觉只读 KV”三者之和反推，而不是先定 batch 再塞草稿。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>长视频/多图稀释注意力</td><td>接受率回落至 0.5–0.6</td><td>验证前向照付、吞吐增益消失</td><td>按模态降 $\\gamma$ 至 2–3</td></tr><tr><td>草稿被换出</td><td>投机命中率骤降、TTFT 抖动</td><td>权重重载带宽、SLO 违约</td><td>常驻配额 + batch 反推</td></tr><tr><td>分布漂移</td><td>连续拒绝率超阈值</td><td>无效并行前向浪费算力</td><td>缩短降 $\\gamma$ 的判定窗口</td></tr></tbody></table>\n<p>第三条边界是反馈回路的时滞。连续拒绝率超阈值后动态降 $\\gamma$ 是唯一的内建保护，但它以历史窗口为判据：当请求分布发生漂移（例如同一 batch 内混入长视频与短问答），阈值触发滞后于真实拒绝，系统会继续以高 $\\gamma$ 做无效并行前向，目标模型算力被空转消耗，而队列里排队的请求 TTFT 被拉长。把判定窗口从“连续 N 次拒绝”改为“滑动窗口内接受 token 数与验证 token 数之比低于阈值即降档”，能让 $\\gamma$ 跟随瞬时接受率而非滞后计数，代价是更频繁的档位切换带来的调度抖动，需要在档位间加迟滞区间以稳定批形状。</p>\n<h3 id=\"alg-cross-stage-vis-spec-sec-14\">十四 · 接受长度的逐位置判定：从拒绝采样到首个截断点</h3>\n<p>跨阶段视觉投机解码的验证逻辑，本质是把标准投机解码的拒绝采样规则原样搬到「视觉条件已固定」的场景里，但每个位置的概率都多了一层跨模态条件。设第 <i>i</i> 个候选位置的草稿分布为 <i>q<sub>i</sub></i>(·|v, x<sub>&lt;i</sub>)，目标分布为 <i>p<sub>i</sub></i>(·|v, x<sub>&lt;i</sub>)，其中 <i>v</i> 是预填阶段写入只读分页池的视觉 KV 摘要。逐位置抽取 <i>u<sub>i</sub></i> ~ U(0,1)，接受判据为</p>\n<div class=\"formula\">$$L_{acc} = \\min\\{i : u_i &gt; p_i/q_i\\}$$</div>\n<p>关键一步在于：<i>p<sub>i</sub></i> 与 <i>q<sub>i</sub></i> 必须在同一视觉条件下求值，否则比值失去意义。工程上这要求草稿模型与目标模型读取的是同一份视觉 KV 摘要向量——不是各自重新编码图像。若草稿侧另做一次轻量视觉编码，<i>q<sub>i</sub></i> 的条件就与 <i>p<sub>i</sub></i> 漂移，<i>p/q</i> 的比值会在视觉相关 token（物体属性、空间关系、计数）上系统性偏离 1，接受率被拉回通用草稿的 0.5–0.6 区间。这就是「共享视觉 KV」不是优化项而是正确性前提的原因。</p>\n<p>截断点确定后，接受前缀的 KV 直接写入分页池，拒绝位置由目标模型重采样一个 token 并继续。代价体现在验证前向的算力上：目标模型对 γ 个候选做一次并行前向，其计算量约等于一次 γ+1 长度的前向，而无论接受多少 token 这笔开销都已付出。因此当 <i>L<sub>acc</sub></i> 很短时，验证前向的算力被浪费——这正是后文动态降 γ 的动机。举例：γ=6 时若首个位置即被拒绝，目标模型仍跑完 7 个位置的并行前向，只提交 1 个重采样 token，等效于用一次长前向换一个 token。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-15\">十五 · 加速比公式的逐项拆解与 γ 的最优解</h3>\n<p>端到端加速比近似为</p>\n<div class=\"formula\">$$\\text{加速比} \\approx \\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)(\\gamma c+1)},\\quad \\alpha = \\mathbb{E}[\\min(1,\\frac{p_{\\text{tgt}}}{p_{\\text{draft}}})]$$</div>\n<p>分子 <i>1−α<sup>γ+1</sup></i> 是「一次投机轮次期望提交的 token 数」的归一化形式：几何分布下接受长度的期望为 <i>(1−α<sup>γ+1</sup>)/(1−α)</i>，即最多 γ 个草稿 token 加 1 个拒绝位重采样。分母拆成两部分：<i>(1−α)</i> 来自接受长度的期望分母，<i>(γc+1)</i> 是每轮的实际时间成本——<i>γc</i> 为草稿模型串行提出 γ 个 token 的相对耗时（<i>c</i> 为草稿单步相对目标单步的成本比），<i>1</i> 为目标模型一次并行验证前向。注意这里把目标验证视为单位成本 1，是因为并行验证 γ+1 个位置的耗时与验证 1 个位置在同一量级（受限于权重加载与 KV 读取带宽，而非算术量）。</p>\n<p>对 γ 求极值可得到工程判断：当 <i>c</i> 很小（草稿模型极轻）时，增大 γ 几乎免费，加速比随 γ 单调上升直至 α<sup>γ+1</sup> 衰减；当 <i>c</i> 接近 1（草稿与目标同量级）时，分母的 <i>γc</i> 迅速吃掉收益，最优 γ 落在个位数。给定事实中 γ=4–8 的配方正对应这一区间：视觉问答接受率 0.75–0.85 时，α=0.8、γ=6、c≈0.1 代入可得分子约 0.74、分母约 1.6，加速比约 2.3 倍，与 1.8–2.4 倍的端到端区间吻合。反过来，若接受率回落到 0.55（长视频场景），同样 γ=6 下分子降到约 0.97、分母不变，加速比跌到 1.5 以下，而验证开销照付。</p>\n<p>这里的关键推导一步是：把「视觉条件」从公式中隐去。α 的定义里 <i>p<sub>tgt</sub></i> 与 <i>p<sub>draft</sub></i> 都隐含以视觉 KV 为条件，因此 α 的提升不是靠调 γ，而是靠让草稿分布向目标分布靠拢。γ 只能放大已有的 α，不能创造 α。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-16\">十六 · 可实现的伪代码：草稿提出与验证循环</h3>\n<p>把机制落到可实现的循环，需要显式区分「视觉 KV 只读」与「文本 KV 可写」两类缓存，并在验证后按接受前缀批量提交。伪代码思路如下：</p>\n<ul>\n<li>预填：ViT 编码 + 跨模态注意力，视觉 KV 写入分页池并打只读标记，摘要向量 <i>s<sub>v</sub></i> 缓存于草稿侧句柄。</li>\n<li>草稿循环：<i>for t in 1..γ</i>，草稿模型以 <i>(s<sub>v</sub>, x<sub>1..k+t−1</sub>)</i> 为输入，采样 <i>y<sub>t</sub></i> 并记录 <i>q<sub>t</sub></i>(y<sub>t</sub>)；草稿 KV 写入临时区，不触碰只读区。</li>\n<li>验证：目标模型对 <i>[x<sub>1..k</sub>, y<sub>1..γ</sub>]</i> 做一次并行前向，得到各位置 <i>p<sub>t</sub></i>；逐位置抽 <i>u<sub>t</sub></i>，按 <i>u<sub>t</sub> ≤ p<sub>t</sub>/q<sub>t</sub></i> 判定，遇首个失败即停。</li>\n<li>提交：接受前缀的草稿 KV 从临时区提升为正式 KV 写入分页池；拒绝位用目标分布重采样一个 token，其 KV 由本次验证前向直接产出，无需重算。</li>\n<li>回退：未接受的草稿 KV 丢弃，临时区按块回收，避免分页碎片。</li>\n</ul>\n<p>代价点在于临时区的显存：γ 个草稿 token 的 KV 在验证完成前必须驻留，若 batch 内多请求并发投机，临时区按 <i>batch × γ × KV_per_token</i> 增长。NVL72 单卡上这与草稿模型权重共同挤压 batch size，构成主要容量约束。一个具体例子：γ=8、batch 内 32 条请求同时投机，临时区需容纳 256 个 token 的 KV，在长上下文模型上这部分可观的显存会直接压低可服务的并发数。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-17\">十七 · 视觉 KV 复用带来的零编码验证与注意力稀释</h3>\n<p>验证阶段「无额外视觉编码开销」不是一句定性描述，而是公式里 <i>γc+1</i> 中那个 <i>1</i> 得以成立的结构性原因：目标模型验证时读取的视觉 KV 就是预填阶段写入的同一份分页块，只读标记保证它不被草稿或验证过程改写。若没有这条复用，每次验证都要重跑 ViT，<i>1</i> 会膨胀为 <i>1 + c<sub>vis</sub></i>，加速比公式的分母被视觉编码成本污染，投机收益在图像分辨率高时迅速归零。</p>\n<p>但复用也带来稀释问题。草稿模型的注意力在视觉 token 数增长时被摊薄：视频或多图输入下，视觉 KV 长度远超文本 KV，草稿模型对「当前该生成哪个文本 token」的条件信号被大量帧间冗余稀释，<i>q<sub>t</sub></i> 向无条件语言模型退化，α 回落到接近通用草稿水平。此时公式分子里的 α<sup>γ+1</sup> 衰减、分母不变，加速比消失而验证开销仍在——这是失败模式而非性能波动。工程对策是按模态动态调 γ：视觉上下文短（单图问答）时 γ 取上限 8，长视频时降到 4 甚至更低，用减少无效并行前向的方式止损。判断依据可直接取滑动窗口内的连续拒绝率，超阈值即降 γ，但降 γ 的滞后性本身是风险：分布漂移时若阈值反应慢，会持续做无效并行前向，浪费目标模型算力。</p>\n<p>另一个隐性代价是草稿模型的显存占用。它与目标模型共享视觉 KV，但自身权重独立驻留。高并发时若草稿模型被换出，投机链路断裂，请求退化为纯自回归解码，吞吐跌回无投机基线，而调度器可能仍按投机路径分配 SLO 预算，造成容量规划失真。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-18\">十八 · 从公式到容量判断：α 与 γ 的联合标定</h3>\n<p>把公式当作容量规划工具而非事后解释，需要固定两个观测量：滑动窗口接受率 α 与草稿单步成本比 c。前者可从验证日志中直接统计（接受 token 数 / 提出 token 数），后者由草稿与目标单步延迟比值测得。给定 α 与 c，对 γ 做一维搜索取加速比最大点，即得该模态、该 batch 下的最优草稿步数。视觉问答场景 α 在 0.75–0.85、c 较小，最优点落在 6–8；长视觉上下文 α 回落到 0.5–0.6 附近，最优点前移到 3–4，且此时加速比本身已不足以覆盖草稿模型的显存机会成本，工程上应考虑对该模态关闭投机、把显存让给 batch size。</p>\n<p>这条判断的落点是：跨阶段视觉投机的收益由 α 主导、由 γ 放大、由 c 与显存约束封顶。α 的上限来自草稿与目标在同一视觉条件下的分布接近程度，而非草稿模型的参数量；把预算花在让草稿更懂图像（共享视觉 KV、摘要向量对齐）比花在加大 γ 上回报更高。当视觉上下文长到稀释不可避免时，正确的动作是降 γ 或退出投机，而不是维持 γ 硬扛——公式分母不会因为「我们希望加速」而变小。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-19\">十九 · 接受长度的分布尾部与 γ 的自适应边界</h3>\n<p>把 $L_{acc}=\\min\\{i:u_i&gt;p_i/q_i\\}$ 逐项拆开看，它的工程含义不是“平均接受几个 token”，而是“拒绝发生在第几个位置”的分布。设单步接受概率为 $\\alpha$，则 $\\Pr[L_{acc}\\ge k]=\\alpha^k$，期望接受长度 $\\mathbb{E}[L_{acc}]=(1-\\alpha^{\\gamma+1})/(1-\\alpha)$。关键的一步推导在于把验证开销折算进分母：目标模型一次并行前向验证 $\\gamma$ 个候选，其代价按 $\\gamma c+1$ 计（$c$ 为草稿单步相对目标单步的算力比），于是得到 $\\text{加速比}\\approx(1-\\alpha^{\\gamma+1})/((1-\\alpha)(\\gamma c+1))$。对 $\\gamma$ 求极值可知最优草稿步数随 $\\alpha$ 单调上升、随 $c$ 单调下降——这解释了为什么视觉问答场景取 $\\gamma=4\\sim8$ 而不是更大：$\\alpha$ 在 0.75–0.85 区间时，继续加大 $\\gamma$ 带来的期望增量被 $c$ 摊薄，尾部拒绝位置几乎全部落在前几步。</p>\n<p>失效条件由此可以直接读出。第一，$\\alpha$ 是期望值而非逐位置常量，长视觉上下文（视频、多图）下草稿模型的注意力被稀释，$\\alpha$ 回落到接近通用草稿的 0.5–0.6 水平，此时公式分子趋近于 1、分母被 $\\gamma c+1$ 放大，加速比跌破 1——验证开销照付，收益消失。第二，$\\alpha$ 的估计滞后于分布漂移：若连续拒绝率阈值触发降 $\\gamma$ 的动作慢于真实分布变化，系统会在错误的 $\\gamma$ 上持续发起无效并行前向，浪费的是目标模型最稀缺的那部分算力。第三，$c$ 不是常数，草稿模型与目标模型共享视觉 KV 时 $c$ 较小，但一旦草稿模型因显存压力被换出、需要重算视觉条件，$c$ 会跳变，公式给出的最优 $\\gamma$ 随之失效。</p>\n<p>落到可实现层面，伪代码的关键是把“接受前缀 KV 直接写入”和“拒绝位置重采样”做成一次原子提交：</p>\n<div class=\"formula\">$$\\begin{aligned}\n&amp;\\text{for } i=1\\ldots\\gamma:\\; u_i\\sim U(0,1),\\;\\; \\text{accept}_i \\leftarrow u_i \\le p_i/q_i\\\\\n&amp;j \\leftarrow \\min\\{i:\\neg\\text{accept}_i\\}\\;\\;\\text{（无拒绝则 } j=\\gamma+1\\text{）}\\\\\n&amp;\\text{commit } KV[1..j-1];\\;\\; x_j \\sim p_j;\\;\\; \\text{reset } \\gamma \\leftarrow f(\\text{recent reject rate})\n\\end{aligned}$$</div>\n<p>这里有两个容易写错的边界。其一，$j=\\gamma+1$ 时不能只提交 $\\gamma$ 个 token 就返回，必须由目标模型补一个位置，否则序列长度与 KV 池的写指针失配。其二，视觉 token 的 KV 在验证中复用不重算，意味着分页池里那段只读区间在整个请求生命周期内不可被换出——它同时是草稿模型的条件输入和目标模型验证的上下文，一旦被驱逐，重算代价直接计入 $c$。系统代价上，草稿模型的显存占用是主要容量约束：NVL72 单卡上 batch size 与草稿模型二选一，高并发时草稿模型被换出会让投机整体失效，此时正确做法是关闭投机、退回纯自回归，而不是保留一个已被换出的草稿路径。工程判断可以写成一条规则：以 $\\alpha$ 的滑动估计和 $c$ 的实测值代入公式，当算出的加速比低于设定下限时直接令 $\\gamma=0$，把决策权交给容量而非固定配置。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-20\">二十 · 边界条件：接受率塌陷与显存挤压下的收益蒸发</h3>\n<p>该方案的加速比并非无条件成立，其收益上界由公式 \\(\\text{加速比} \\approx \\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)(\\gamma c+1)}\\) 直接刻画。推导的关键一步在于把“每轮验证的期望产出 token 数”与“每轮的实际代价”分开：分子 \\(1-\\alpha^{\\gamma+1}\\) 除以 \\(1-\\alpha\\) 给出几何级数形式的期望接受长度，分母中的 \\(\\gamma c+1\\) 则是草稿自回归 \\(\\gamma\\) 步（每步代价系数 \\(c\\)）加目标模型一次并行前向的归一化代价。当 \\(\\alpha\\) 从视觉问答的 0.75–0.85 回落到通用草稿的 0.5–0.6 时，分子增长趋缓而分母被 \\(\\gamma c\\) 撑大，加速比迅速向 1 收敛——这意味着验证开销照付、收益归零。失效条件因此可以写得很具体：视频或多图长视觉上下文使草稿模型注意力被稀释，接受率塌陷到接近通用草稿水平，此时继续以 \\(\\gamma=4\\text{–}8\\) 做并行前向就是纯亏损。</p>\n<p>第二个边界是容量而非算法。草稿模型额外占用显存，在 NVL72 单卡上直接与 batch size 争夺同一块 HBM 预算；高并发时草稿模型被换出，投机链路断裂，请求退化为逐 token 自回归，而此时调度器仍在按“有投机”的假设做容量规划，SLO 会被静默击穿。工程判断应把草稿模型视为与 KV cache 同级的容量项，而不是免费附加物：给定显存上限，可服务的并发数 \\(B\\) 与 \\(\\gamma\\) 之间存在此消彼长，长视觉上下文下 KV 池本身膨胀，草稿模型的生存空间进一步压缩。</p>\n<p>第三个边界是动态降 \\(\\gamma\\) 的滞后性。连续拒绝率超阈值后降 \\(\\gamma\\) 是正确方向，但阈值判定基于滑动窗口，分布漂移（例如 agent 从图像问答切换到多轮指代推理）发生时窗口尚未更新，系统会持续做无效并行前向，浪费目标模型算力。可实现的伪代码思路是：以最近 \\(W\\) 轮的接受长度 \\(L_{acc}=\\min\\{i: u_i &gt; p_i/q_i\\}\\) 均值作为控制信号，若低于阈值则 \\(\\gamma \\leftarrow \\max(1, \\lfloor \\gamma/2 \\rfloor)\\)，并同步下调该请求的 batch 占位，避免“降了 \\(\\gamma\\) 却没释放显存”的半失效状态。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>长视频/多图稀释注意力</td><td>接受率回落至 0.5–0.6 区间</td><td>验证前向照付，加速比趋近 1</td><td>按模态降 \\(\\gamma\\)，必要时关闭投机</td></tr><tr><td>草稿模型被换出</td><td>草稿延迟尖峰、投机命中率骤降</td><td>batch size 与草稿二选一</td><td>预留常驻显存配额</td></tr><tr><td>降 \\(\\gamma\\) 滞后</td><td>连续拒绝率超阈值但窗口未更新</td><td>无效并行前向浪费算力</td><td>缩短窗口、按请求粒度控制</td></tr></tbody></table>\n<h3 id=\"alg-cross-stage-vis-spec-sec-21\">二十一 · 请求形态：短视觉上下文与高文本熵的匹配面</h3>\n<p>跨阶段视觉投机解码的负载配方不是“所有多模态请求都更快”，而是一条窄带：视觉上下文短、问题指向图像中局部证据、答案文本有一定长度且分布可预测。视觉问答恰好落在这条带上——图像经 ViT 编码后视觉 KV 只读驻留，草稿模型读取视觉 KV 摘要向量与当前文本，自回归提出 γ=4–8 个候选，目标模型一次并行前向验证。此时草稿分布与目标分布接近，接受率从通用草稿的 0.5–0.6 提升到 0.75–0.85，端到端解码吞吐提升 1.8–2.4 倍。</p>\n<p>把请求按“视觉 token 数 × 期望输出长度”分格，可以看清配方边界。视觉 token 少（单图、低分辨率切片）、输出长（描述、多步推理链）的格子收益最大：γ 个候选被接受的比例高，摊薄了每次验证的目标模型前向。视觉 token 多、输出短（单字判别、分类）的格子收益最小：验证前向的固定开销无法被少量解码步摊薄，投机反而增加调度复杂度。工程上应把前者放进投机通道，后者走普通解码通道，用路由而非全局开关。</p>\n<p>公式给出配方敏感度。接受率 α 与草稿步数 γ 共同决定加速比：</p>\n<div class=\"formula\">$$\\text{加速比} \\approx \\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)(\\gamma c+1)},\\quad \\alpha = \\mathbb{E}[\\min(1,\\frac{p_{\\text{tgt}}}{p_{\\text{draft}}})]$$</div>\n<p>其中 c 为单次验证前向相对单步解码的代价系数。α 从 0.6 升到 0.8 时，同一 γ 下分子显著变大；但 γ 增大也会放大分母中的 γc。视觉问答场景 α 高，γ=4–8 是甜点区；一旦 α 回落到 0.6 附近，增大 γ 只会让分母线性膨胀而分子趋饱和，加速比迅速退化到 1 附近甚至低于 1。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-22\">二十二 · 长度分布：输出长度决定摊薄，视觉长度决定稀释</h3>\n<p>输出长度分布是第一个配方变量。投机解码的收益来自“一次验证前向换多个被接受 token”，因此期望输出长度必须显著大于 γ。若请求的输出长度集中在十几个 token（例如结构化抽取的短字段），γ=8 的候选序列经常在第一个拒绝位置就被截断，接受前缀很短，验证开销却按整段候选付出。反过来，长输出请求让每个验证前向的固定成本被多次接受摊薄，α 的微小提升会沿解码步累积成吞吐差。</p>\n<p>视觉长度分布是第二个变量，且方向相反。视频或多图长视觉上下文下，草稿模型的注意力被大量视觉 token 稀释，跨模态条件信号变弱，草稿分布向通用语言先验回退，接受率回落到接近通用草稿水平。此时加速比消失，而验证开销仍在：目标模型仍要对 γ 个候选做并行前向，视觉 KV 仍要在分页池中占用带宽。这是配方失配最典型的形态——成本结构没变，收益结构塌了。</p>\n<p>两个分布要联合看。设输出长度 L、视觉 token 数 V，配方可写成“L/γ 足够大且 V 足够小”。工程上不需要精确建模，只需在请求进入调度器时打两个标签：预估输出长度档位与视觉 token 档位。短输出或长视觉任一命中，就把该请求移出投机通道。这个路由判断的成本远低于一次无效验证前向。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-23\">二十三 · 并发与批大小：草稿模型的显存挤占是硬约束</h3>\n<p>并发维度上，跨阶段投机解码有一个不同于纯文本投机的约束：草稿模型与目标模型共享视觉 KV，验证阶段无额外视觉编码开销，但草稿模型本身额外占用显存。在 NVL72 单卡上，这直接表现为 batch size 与草稿模型二选一——留给 KV cache 与激活的显存被草稿权重切走一块，连续批处理能容纳的并发序列数下降。</p>\n<p>这条约束改变容量曲线形状。普通解码服务中，吞吐随 batch size 上升直到带宽或算力饱和；加入草稿模型后，饱和点左移。更麻烦的是高并发下的换出行为：当调度器为保住 batch size 把草稿模型换出，投机通道整体失效，请求退回普通解码，此前按投机收益做的 SLO 预算全部落空。因此配方必须把“草稿模型常驻”作为不可协商项，用降低 batch size 而非换出草稿来吸收压力。</p>\n<p>批内异质性也会侵蚀收益。连续批处理把不同请求拼进同一批，若批内混有长视觉上下文请求，其低接受率会拉低整批的有效接受长度，而验证前向是按批付代价的。配方做法是按视觉 token 档位分桶：短视觉请求聚成一批走高 γ，长视觉请求单独成批走低 γ 或普通解码。分桶会牺牲一点批填充率，但换回的是接受率的可预测性。</p>\n<p>显存账要算清三块：草稿权重、目标权重、分页 KV 池。视觉 KV 标记为只读并在验证中复用不重算，这省掉了重复编码，但不省显存——只读意味着它必须常驻。并发上限由“总显存减去两份权重后剩下的 KV 池”决定，而不是由目标模型单独决定。容量规划时若沿用纯文本服务的 batch size 经验值，会直接超配。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-24\">二十四 · 负载不对时的三种失效形态</h3>\n<p>第一种是长视觉稀释型。视频或多图请求进入投机通道，草稿模型注意力被稀释，接受率回落到通用草稿水平，加速比消失而验证开销仍在。系统表现为 GPU 利用率不低、吞吐不涨、尾延迟变差——因为每个解码步都多了一次并行验证前向。识别信号是滚动窗口接受率跌破阈值且视觉 token 数同步偏高，处置是把该模态整体移出投机通道，而不是继续调 γ。</p>\n<p>第二种是显存挤压型。高并发时草稿模型被换出，投机失效，且换入换出本身带来调度抖动。更隐蔽的版本是草稿模型未被换出但 KV 池被压缩到接近下限，分页池频繁回收，视觉 KV 的只读页被反复换入，带宽被非计算流量吃掉。识别信号是 KV 池命中率下降与投机接受率同时恶化，处置是降并发而非降 γ。</p>\n<p>第三种是降 γ 滞后型。连续拒绝率超阈值后动态降 γ 是既定稳定性技巧，但若阈值判定滞后，分布漂移期间系统会持续做无效并行前向，浪费目标模型算力。典型场景是请求从短视觉问答切到长文档多图问答，α 已跌落而 γ 仍停在 8，每个解码步都在为注定被截断的候选付验证代价。处置是把拒绝率判定窗口缩短，并让 γ 的调整与视觉 token 档位联动，而不是只看历史接受率。</p>\n<p>三种失效的共同点是：成本结构（验证前向、显存占用、带宽）没有随负载变化，收益结构（接受长度）却变了。配方的工作就是让通道选择跟随收益结构，而不是让系统在失配状态下靠动态调参硬撑。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-25\">二十五 · 配方落地：路由、分桶与 γ 的联动</h3>\n<p>落地配方可写成三段式。入口路由按“预估输出长度 ≥ 数倍 γ”且“视觉 token 数低于档位阈值”筛入投机通道；批调度按视觉 token 档位分桶，短视觉桶配高 γ，长视觉桶配低 γ 或普通解码；运行期监控以滚动接受率为准，连续拒绝率超阈值时降 γ，且降 γ 后若接受率不恢复则整桶退出投机通道。三段各自独立生效，避免单点调参把整条通道拖垮。</p>\n<p>γ 的选择要与批大小联动而非独立调。γ 增大提高单请求接受长度，但也增大每次验证前向的候选长度，在批内异质时放大最慢请求的尾延迟。工程判断是：批大小高、批内同质时用 γ 上限；批大小低或批内混有长视觉请求时用 γ 下限。视觉问答场景 α 在 0.75–0.85，γ=4–8 的区间内加速比对 γ 不敏感，因此优先用 γ 换批内同质性，而不是追求单请求最优 γ。</p>\n<p>容量规划要留出草稿模型的固定显存份额，并据此反推 batch size 上限与 SLO 可达区间。共享视觉 KV、验证不重算视觉编码这两点让投机通道的边际成本主要落在草稿权重与验证前向上，因此配方评估应看“每 token 分摊的验证前向次数”与“每序列占用的 KV 页数”两个指标，而不是看单请求加速比。前者决定算力饱和点，后者决定并发上限。</p>\n<p>最后一条工程判断：这条通道的适用边界是视觉上下文较短、草稿与目标分布接近的场景。边界之外不是调参问题，是配方问题——把请求路由出去比在失配负载上优化 γ 更省算力。跨阶段视觉投机解码的负载配方，本质是把“视觉条件下的高接受率”当成一种稀缺资源来分配，而不是当成默认属性来假设。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-26\">二十六 · 负载配方：短视觉上下文、中高并发、偏问答型请求才是它的舒适区</h3>\n<p>这套方案吃的是“视觉上下文短、文本生成占主导、请求形态偏问答”的负载。视觉问答与多模态 agent 在线服务里，预填阶段的 ViT 编码与跨模态注意力一次性完成，视觉 KV 写入分页池并标为只读，之后解码阶段的成本几乎全落在文本 token 的串行生成上——这正是投机解码能插进去的位置。草稿模型读视觉 KV 摘要向量加当前文本，自回归提出 γ=4–8 个候选，目标模型一次并行前向验证。此时接受率能到 0.75–0.85，端到端解码吞吐提升 1.8–2.4 倍。反过来，如果请求以长文本续写为主、图像只作点缀，视觉条件对草稿分布的约束就很弱，接受率退回通用草稿水平（0.5–0.6），加速比按公式收缩：</p>\n<div class=\"formula\">$$\\text{加速比} \\approx \\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)(\\gamma c+1)},\\quad \\alpha = \\mathbb{E}[\\min(1,\\frac{p_{\\text{tgt}}}{p_{\\text{draft}}})]$$</div>\n<p>α 掉到 0.55 附近时，γ 再大也换不来线性收益，而验证前向的开销照付。长度分布上，输出长度中等（几十到几百 token）的请求摊薄了草稿模型的固定开销；极短回答里投机几乎无利可图，极长生成则让拒绝累积放大。</p>\n<p>并发与批大小是更硬的约束。草稿模型额外占显存，在 NVL72 单卡上它与 batch size 是二选一的关系：要把 batch 拉高吃满解码吞吐，就得压缩草稿模型的空间；草稿模型被换出，投机直接失效，退化成纯目标模型解码。因此这套方案的容量规划要按“草稿常驻 + 目标模型 + 分页 KV 池”三者分账，而不是只看目标模型。高并发下若调度器把草稿模型当可抢占资源，尾延迟会出现阶跃式恶化——被抢占的那批请求既没有投机收益，又多了排队等待。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>接受率走向</th><th>系统代价</th></tr></thead><tbody><tr><td>短视觉上下文 + 问答型</td><td>0.75–0.85，γ=4–8 有效</td><td>草稿显存换吞吐，收益为正</td></tr><tr><td>长视频 / 多图</td><td>回落至接近通用草稿</td><td>验证开销仍在，加速比消失</td></tr><tr><td>高并发 + 草稿被换出</td><td>投机路径不可用</td><td>吞吐退回基线，尾延迟抖动</td></tr></tbody></table>\n<p>失效条件集中在两处。其一是长视觉上下文：视频或多图输入让草稿模型的注意力被稀释，视觉条件不再锐利，接受率回落，而目标模型的并行验证前向一分不少，等于用额外算力买了个接近零的加速。其二是分布漂移下的 γ 滞后：连续拒绝率超阈值才动态降 γ，若阈值判定慢于请求分布变化，系统会持续做无效并行前向，白白消耗目标模型算力。工程判断是：把 γ 的调节做成按模态与近期接受率的滑动估计，而不是事后补救；同时在准入层按视觉 token 数分流，长上下文请求走非投机路径，短上下文请求才进投机队列。</p>\n<h3 id=\"alg-cross-stage-vis-spec-sec-27\">二十七 · 硬件档位：按显存与算力切三档</h3>\n<p>跨阶段视觉投机解码的部署起点不是“买什么卡”，而是“草稿模型和目标模型能否同时常驻”。视觉 KV 在预填后写入分页池并标只读，草稿与目标共享这份 KV，验证阶段不再重算视觉编码——这条机制把显存账目切成两块：视觉 KV 的常驻占用，以及草稿模型权重与其运行时激活。NVL72 单卡上，草稿模型额外占用显存，直接与 batch size 争夺同一块 HBM，这是本方案的主要容量约束。按此约束划三档：<b>单卡档</b>（B200/B300 单卡，草稿模型与目标模型共卡，batch 小、γ 取上限 4–8 中的低段，视觉上下文限单图短提示）；<b>双卡档</b>（草稿模型独占一张卡或一个 MIG 切片，目标模型独占另一张，视觉 KV 通过 NVLink 5 共享只读副本，batch 可放大，γ 取中段）；<b>NVL72 机柜档</b>（草稿模型作为独立副本池，按模态与并发弹性伸缩，目标模型按 TP/EP 拓扑铺开，视觉 KV 池集中管理）。档位选择的判据是每卡可容纳的并发序列数：草稿权重占掉的 HBM 若使 batch 掉到单序列，投机收益被吞吐损失吃掉，此时应升档而非降 γ。三档共用一条公式来估收益上界：</p>\n<div class=\"formula\">$$\\text{加速比} \\approx \\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)(\\gamma c+1)},\\quad \\alpha = \\mathbb{E}[\\min(1,\\frac{p_{\\text{tgt}}}{p_{\\text{draft}}})]$$</div>\n<p>其中 c 为草稿模型单步相对目标模型单步的代价比。单卡档 c 偏大（草稿与目标争同一份算力与带宽），双卡档 c 因并行而下降，机柜档 c 最小但引入跨卡通信。视觉问答场景 α 落在 0.75–0.85，若 c 接近 0.2、γ=6，加速比落在 1.8–2.4 倍区间内；一旦草稿被换出、投机退化为纯目标解码，c 的收益项归零而验证开销仍在，加速比塌回 1 以下。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-28\">二十八 · 并行拓扑：草稿与目标的切分方式</h3>\n<p>拓扑的核心矛盾是：草稿模型需要低延迟单步（它自回归提 γ 个候选），目标模型需要高吞吐并行前向（一次验证 γ+1 个位置）。两者对并行的偏好相反。工程上三种切法：<b>共卡共 TP</b>，草稿与目标同 TP 组、分时复用 SM，靠 tcgen05 与 TMEM 的流水让草稿步与验证步交错，省通信但草稿步延迟被目标侧排队拉长；<b>共卡分 SM</b>，用 SM 分区把草稿固定在少量 SM 上跑小 batch，目标吃剩余 SM，适合单卡档；<b>分离部署</b>，草稿模型独立副本、目标模型按 2-SM MMA 与 EP 铺开，视觉 KV 只读副本经 NVLink 5 广播，NCCL 负责权重同步、NIXL 负责 KV 与候选 token 的点对点传输。分离部署的代价是每轮验证多一次候选序列的跨卡搬运，候选 token 数量小（γ+1 个位置、每位置词表 logits 或采样结果），带宽开销可忽略，但引入一次往返时延，必须与目标模型一次前向的时长对齐，否则流水空转。拓扑选择的一条硬判据：验证步的并行前向必须占满目标侧 MMA 流水，若 γ 太小导致验证 batch 撑不满，2-SM MMA 的配对收益消失，此时应提高 γ 或合并多条序列的候选一起验证（多序列投机批）。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-29\">二十九 · 量化方案：草稿与目标的不对称精度</h3>\n<p>量化不能两边用同一套。目标模型的输出分布 p_tgt 决定接受判定，其数值精度直接影响 α：目标侧若用 NVFP4 压权重而激活保持 FP8，逐位置比对时 p_tgt 的尾部概率被粗化，min(1, p_tgt/p_draft) 的期望被系统性拉低，α 下滑。草稿模型只提供提议分布 q_draft，其精度可以更激进——草稿用 NVFP4 权重加 FP8 激活，甚至草稿的视觉条件分支用更低比特，因为草稿分布偏差会被拒绝机制纠正，代价只是 α 略降而非正确性损失。工程配方：目标模型权重 NVFP4、激活与 KV 用 FP8，跨模态注意力与输出头保持 FP8 或 BF16 以稳住 p_tgt 的尾部；草稿模型权重 NVFP4、激活 FP8，视觉 KV 摘要向量用 FP8 存储以省带宽。视觉 KV 本身在预填后只读，量化一次即固化，验证阶段复用不重算，因此视觉 KV 的量化误差只发生一次、不随解码步累积——这是本方案相对逐层压缩类方法的部署优势。代价面：目标侧 FP8 激活使每 token 的 KV 写入带宽减半，但 NVFP4 权重的反量化在 MMA 前引入额外指令，若 tcgen05 的缩放因子通路未对齐，单步延迟反而上升；草稿侧激进量化使 α 从 0.85 档滑向 0.75 档，需用 γ 上调补偿。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-30\">三十 · KV 策略：只读视觉池与可写文本池分离</h3>\n<p>KV 策略必须按“只读/可写”分池，否则分页分配器会在视觉 KV 上做无谓的换入换出。视觉 KV 在预填完成时写入分页池并标记只读，草稿模型读取的是视觉 KV 摘要向量而非全量视觉 KV，目标模型验证时直接引用同一物理页。文本 KV 走常规分页池，接受前缀 token 的 KV 直接写入、拒绝位置由目标模型重采样后写入。三个工程要点：其一，只读页的引用计数在草稿与目标之间共享，避免复制；其二，视觉 KV 摘要向量的粒度要与 γ 对齐——摘要太粗则草稿对图像不敏感、α 退回 0.5–0.6 的通用水平，太细则草稿每步读取的带宽吃掉收益，实践中按视觉 token 数分块、每块一个摘要，块数与 γ 同量级；其三，长视觉上下文（视频、多图）下草稿注意力被稀释，α 回落，KV 策略要配合模态标签做分级：短视觉上下文用全摘要，长上下文只保留关键帧摘要并同步降 γ。显存代价：只读视觉池常驻不释放，在多轮对话中跨请求复用可摊薄；但草稿模型的摘要向量缓存是额外开销，NVL72 单卡上它与草稿权重一起挤压 batch，构成“batch size 与草稿模型二选一”的容量墙。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-31\">三十一 · 调度参数：γ 的动态控制与拒绝率阈值</h3>\n<p>调度层要管三组参数：γ、批组成、拒绝率阈值。γ 的静态初值按档位给（单卡 4、双卡 6、机柜 8），运行时按连续拒绝率动态下调——连续拒绝率超阈值时降 γ，因为无效并行前向浪费的是目标模型算力，而目标模型是稀缺资源。伪代码思路：</p>\n<ul>\n<li>每轮验证后更新滑动窗口拒绝率 r；若 r &gt; r_hi，γ ← max(γ_min, γ−1)；若 r &lt; r_lo 且队列深度足够，γ ← min(γ_max, γ+1)。</li>\n<li>模态标签为视频/多图时，γ 上限直接压到低段，不等待拒绝率触发。</li>\n<li>批组成按“视觉上下文长度分桶”，同桶序列共享视觉 KV 页与相近的 α，避免长短视觉上下文混批导致桶内 α 方差过大、动态 γ 反复震荡。</li>\n</ul>\n<p>阈值设定的陷阱是滞后：分布漂移时若降 γ 慢于 α 下滑，系统会持续做无效并行前向，目标算力被空转消耗，表现为吞吐不升反降而延迟抖动。因此 r_hi 应偏保守（宁可早降），r_lo 偏激进（宁可晚升），形成不对称回滞。调度参数与 SLO 的耦合在于：γ 越大单轮验证越重、尾延迟越高，面向严格 TPOT 的在线服务应把 γ 上限与 batch 上限联合约束，而不是单独调 γ。容量规划上，草稿模型副本数按模态流量配比弹性伸缩，高并发时草稿被换出即投机失效，必须为草稿预留不可换出的常驻配额。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-32\">三十二 · 可复现配置思路：从约束反推参数</h3>\n<p>给出一条可复现的推导链，而非一组拍脑袋数字。第一步，测目标模型在目标精度下的单步解码延迟与每 token KV 写入带宽，得到纯目标解码的吞吐基线。第二步，测草稿模型单步延迟，算 c；c 超过 0.3 时共卡方案不成立，直接选分离部署。第三步，用视觉问答验证集估 α，短视觉上下文预期 0.75–0.85，长视频/多图预期回落至接近通用草稿水平，据此给每个模态桶设 γ 上限。第四步，用加速比公式反解：给定目标加速比 1.8–2.4 倍与实测 α、c，求出 γ 的可行区间，取区间下沿作为静态初值，留上调空间给动态控制。第五步，算显存账：视觉只读池 + 草稿权重 + 草稿摘要缓存 + 目标 KV 池，剩余 HBM 决定最大并发序列数，若该数小于 SLO 所需并发，则升档或对草稿做更激进的量化。第六步，压测拒绝率回滞参数，确认分布漂移时 γ 下调先于吞吐塌陷。整条链的产出是一份按模态分桶的配置表：档位、TP/EP 拓扑、草稿与目标的精度组合、视觉 KV 摘要粒度、γ 初值与上下限、r_hi/r_lo。可复现的关键在于每一步都由实测 α 与 c 驱动，而非套用固定模板；视觉问答的 1.8–2.4 倍是这条链在短视觉上下文、草稿与目标分布接近条件下的落点，长视觉上下文下同一配置会退化，必须靠模态分桶与动态 γ 兜住。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-33\">三十三 · 视觉投机解码的部署边界：显存预算、模态漂移与 γ 的失效条件</h3>\n<p>这套配方的容量约束不在算力而在显存：草稿模型与目标模型共享视觉 KV，验证阶段不重算视觉编码，但草稿权重本身要占一份常驻显存。在 NVL72 单卡上，batch size 与草稿模型是此消彼长的关系——把草稿模型常驻，就压缩了可并发的请求数；把 batch 拉满，草稿模型在高并发下被换出，投机路径直接失效，退化成目标模型逐 token 自回归，而调度器仍在按投机模式分配时间片，形成“配置在、收益无”的空转。工程判断是：先按 SLO 反推所需并发，再决定草稿模型是常驻、分时驻留还是按模态路由——视觉问答短上下文请求走投机路径，长视频请求直接走非投机路径，避免为低收益流量支付显存代价。</p>\n<p>接受率 α 是这套方案唯一的经济性变量，而 α 对视觉上下文长度高度敏感。视频或多图输入下，草稿模型的注意力被稀释，跨模态条件退化为近似通用草稿，α 回落到 0.5–0.6 区间；此时按公式</p>\n<div class=\"formula\">$$S \\approx \\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)(\\gamma c+1)}$$</div>\n<p>分子随 α 下降而收缩，分母中的 γc 却不变，加速比趋近于 1 以下——验证的并行前向照做，收益消失，等于用目标模型的算力买了一次无效比对。因此 γ 不能是静态超参，必须按模态与上下文长度分档：短视觉上下文取 γ=4–8 的上沿，长视频取低档甚至关闭投机。连续拒绝率阈值触发降 γ 是必要的，但滞后本身就是代价：分布漂移时若降 γ 慢于 α 的下跌，系统会持续做无效并行前向，浪费的正是最紧张的目标模型算力。</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>草稿驻留</th><th>γ</th><th>适用模态</th><th>主要代价</th></tr></thead><tbody><tr><td>短视觉上下文</td><td>常驻</td><td>4–8</td><td>单图 VQA、agent 短观察</td><td>草稿显存挤压 batch</td></tr><tr><td>多图/中等上下文</td><td>常驻，降 γ</td><td>低档</td><td>多图问答</td><td>α 回落，加速比收窄</td></tr><tr><td>长视频</td><td>按需或关闭</td><td>关闭</td><td>视频理解</td><td>验证开销纯损耗</td></tr></tbody></table>\n<p>量化方案上，草稿与目标不必同精度：草稿只承担提议，分布偏差由目标验证兜底，草稿侧用更低比特换取显存与带宽，把省下的显存还给 batch；目标侧保持与线上一致的精度，因为验证比对的是目标分布本身，量化误差会直接改写接受判定。并行拓扑上，视觉 KV 只读且跨请求复用，适合放在分页池的共享段，而草稿的文本 KV 按请求私有，两者生命周期不同，混在同一池里会导致只读段被频繁换出。最终的可复现配置思路是：以模态路由为第一层分流，以显存预算定草稿驻留策略，以拒绝率反馈闭环调 γ，三者任一失配，1.8–2.4 倍的吞吐收益就会退回 1 倍而验证成本照付。</p>\n<h3 id=\"alg-cross-stage-vis-spec-sec-34\">三十四 · 显存墙：草稿模型与 batch size 的二选一</h3>\n<p>跨阶段视觉投机解码在容量上的第一道约束不是 KV cache，而是草稿模型本身。视觉 KV 在预填后写入分页池并标记只读，验证阶段复用不重算，这部分显存是共享的、可预期的；但草稿模型是一份额外的权重常驻，它与目标模型在同一张 SM100 上争夺 HBM。NVL72 单卡（GB200 的一个 compute tray 切片）的显存预算要同时容纳目标模型权重、草稿权重、分页 KV 池和运行时 workspace，四者之中只有草稿权重是\"可以不要\"的，于是容量规划自然退化为一个二选一：给定 SLO 下的最大并发 batch size，与草稿模型的驻留，二者只能取其一。</p>\n<p>把这件事写成约束更清楚。设单卡显存为 \\(M\\)，目标权重 \\(W_t\\)、草稿权重 \\(W_d\\)、每请求视觉 KV 为 \\(K_v\\)、每请求文本 KV 为 \\(K_x(b)\\)（随 batch 内序列长度增长），则可行 batch 满足</p>\n<div class=\"formula\">$$B \\le \\frac{M - W_t - W_d - M_{\\text{ws}}}{K_v + K_x(b)}$$</div>\n<p>草稿模型进入分子中的减项，直接压低 \\(B\\) 的上界。工程上的判断点在于：投机解码的收益是解码阶段的吞吐倍数（视觉问答下 1.8–2.4 倍），而代价是 \\(B\\) 的下降。若 \\(B\\) 从 \\(B_0\\) 降到 \\(B_0 - \\Delta\\)，总吞吐的变化近似为两条曲线的乘积，只有当解码阶段在端到端时间里占比足够高时，投机才净赚。多模态 agent 的负载里预填占比不低（ViT 编码 + 跨模态注意力），这正是收益被侵蚀的地方。高并发下更糟的情形是草稿模型被换出到 host 或远端，投机路径直接失效——不是变慢，而是退化回逐 token 自回归，同时验证开销的代码路径还在。</p>\n<p>具体例子：一个视觉问答服务，单请求视觉上下文为数十个视觉 token、文本 KV 随对话增长。若草稿权重占用相当于目标权重的可观比例，则在同一张卡上把 batch 翻倍与保留草稿，是互斥的两个容量方案；前者提升的是并发度，后者提升的是单请求解码速度，二者对尾延迟的作用方向相反。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-35\">三十五 · 带宽账：验证前向的算术强度与视觉 KV 的只读复用</h3>\n<p>解码阶段的目标模型前向在 batch 较小时是带宽受限的：每生成一个 token 要读一遍权重与 KV。投机解码把 \\(\\gamma\\) 个候选放进一次并行前向，等于把同一批权重读取摊到 \\(\\gamma+1\\) 个位置上（\\(\\gamma\\) 个候选加一个重采样位置），算术强度随之上升，这是投机在带宽维度上的根本收益。但跨阶段视觉投机多了一层：草稿模型每步都要读视觉 KV 摘要向量，目标模型验证时也要对视觉 KV 做注意力。视觉 KV 被标记只读并在验证中复用，省掉的是重算，不是读取——它仍然占带宽。</p>\n<p>于是带宽账要分两块记。第一块是权重带宽：目标模型一次前向读 \\(W_t\\)，产出至多 \\(\\gamma+1\\) 个 token，单位 token 的权重带宽成本降为原来的 \\(1/(\\gamma+1)\\) 量级，实际按接受长度折算。第二块是 KV 带宽：视觉 KV 长度 \\(L_v\\) 固定且不随解码增长，文本 KV 长度 \\(L_x\\) 随步数增长，单步 KV 读取量为 \\((L_v + L_x) \\cdot d \\cdot\\) 字节数。当 \\(L_v\\) 远大于 \\(L_x\\) 时（长视觉上下文），KV 带宽被视觉部分主导，而视觉部分在草稿与目标之间是共享的——共享省的是显存与重算，不省读取。这就是长视觉上下文下投机收益衰减的带宽解释：验证前向的固定成本被 \\(L_v\\) 抬高，而接受率却在下降，两头挤压。</p>\n<p>用接受率公式看更直接：</p>\n<div class=\"formula\">$$\\text{加速比} \\approx \\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)(\\gamma c+1)},\\quad \\alpha = \\mathbb{E}[\\min(1,\\frac{p_{\\text{tgt}}}{p_{\\text{draft}}})]$$</div>\n<p>其中 \\(c\\) 是草稿单步相对目标单步的成本比。跨阶段视觉投机把 \\(\\alpha\\) 从通用草稿的 0.5–0.6 抬到 0.75–0.85，分子分母同时改善；但 \\(c\\) 并不为零，草稿模型自回归提出 \\(\\gamma=4–8\\) 个候选本身要读视觉摘要与文本 KV。当 \\(\\alpha\\) 回落到接近 0.5 时，\\(\\gamma c\\) 项开始主导分母，加速比趋近于 1 以下——即投机变成净亏损。视频或多图场景正是这条路径：草稿模型注意力被稀释，\\(\\alpha\\) 掉回通用水平，而验证开销仍在。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-36\">三十六 · 通信面：分离式部署下视觉 KV 的搬运与只读语义</h3>\n<p>在预填/解码分离的拓扑里（预填节点做 ViT 编码与跨模态注意力，解码节点做自回归），视觉 KV 必须从预填侧传到解码侧。跨阶段视觉投机的机制要求草稿模型读取视觉 KV 摘要向量，目标模型验证时复用同一份视觉 KV——这意味着视觉 KV 在解码侧要被两个模型同时引用，且标记只读。只读语义在通信上的价值是：它允许一次传输、多方引用，不需要在草稿与目标之间做 KV 的来回同步；代价是这份 KV 在解码侧的分页池里必须常驻，不能像文本 KV 那样随请求结束立即回收，容量压力因此比纯文本服务更刚性。</p>\n<p>搬运量可以估：单请求视觉 KV 字节数为 \\(L_v \\cdot d \\cdot s\\)（\\(s\\) 为每元素字节数，NVFP4/FP8 下显著小于 BF16）。在 NVLink 5 域内这条传输相对便宜，跨节点则要走 NIXL 之类的传输层，带宽成为预填到解码的排队项。关键判断是：视觉 KV 的传输是每请求一次的固定开销，而投机省下的是每步的串行延迟，二者不在同一时间尺度上——请求数上升时，传输开销线性增长，投机收益按请求并行摊薄，交叉点出现在并发足够高、传输链路饱和的位置。此时先崩的不是算力，是预填到解码的链路。</p>\n<p>具体例子：NVL72 机架内，预填与解码分处不同 tray，视觉 KV 经 NVLink 交换机搬运。若单请求视觉上下文较长，视觉 KV 传输占用链路的时间可与该请求的解码时间相比，分离式拓扑的收益被传输吃掉；把草稿模型放在解码侧、视觉 KV 只传一次，是这套机制在通信上的正确落点。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-37\">三十七 · 功耗与热：验证前向的瞬时功率尖峰</h3>\n<p>投机解码的功耗特征与常规解码不同。常规自回归每步是一次小 batch 前向，功率相对平稳；投机验证是一次 \\(\\gamma+1\\) 位置的并行前向，tcgen05 的 MMA 在短时间内被拉满，TMEM 与 2-SM MMA 的利用率瞬时抬升，形成功率尖峰。跨阶段视觉投机还叠加了草稿模型的自回归段——草稿段是低利用率、高频率的小前向，验证段是高利用率、短时的大前向，两段交替使单卡的功率曲线呈锯齿状。</p>\n<p>这在 NVL72 这种高密度机架上是容量问题而非性能问题：机架级功率预算按平均值分配，但尖峰决定散热与供电的瞬时余量。工程上的做法是把 \\(\\gamma\\) 与 batch 一起纳入功率约束——\\(\\gamma\\) 越大，验证前向的瞬时并行度越高，尖峰越陡；\\(\\gamma=4–8\\) 的取值区间本身就是功率与接受率的折中。动态降 \\(\\gamma\\) 的触发条件若只看拒绝率，会漏掉功率维度：连续高 \\(\\gamma\\) 验证在功率受限的机架上可能触发降频，而降频又拉长验证时间，反过来压低有效吞吐。</p>\n<p>代价的定性表述：草稿段与验证段的交替使 SM 的占用率在两个极值间跳变，能效（每 token 焦耳）在 \\(\\alpha\\) 高时优于纯自回归，在 \\(\\alpha\\) 低时劣于纯自回归——因为验证前向做了 \\(\\gamma+1\\) 份工作却只提交了少量 token。这是\"加速比消失而验证开销仍在\"的功耗版本。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-38\">三十八 · 尾延迟：拒绝截断与动态 γ 的滞后</h3>\n<p>投机解码对尾延迟的影响是不对称的。接受长度 \\(L_{acc} = \\min\\{i : u_i &gt; p_i/q_i\\}\\) 是一个随机变量，其分布右尾对应\"一次接受很多 token\"的快路径，左尾对应\"首个位置就被拒绝\"的慢路径——后者意味着目标模型做了一次 \\(\\gamma+1\\) 位置的并行前向，却只提交了一个重采样 token，单步有效吞吐低于纯自回归。P99 延迟由左尾决定，而均值由右尾拉低。跨阶段视觉投机把 \\(\\alpha\\) 抬到 0.75–0.85，左尾概率下降，但因为 \\(\\gamma\\) 更大（4–8），单次拒绝的浪费也更大：拒绝发生在第 \\(i\\) 位时，前 \\(i\\) 位的验证计算全部作废。</p>\n<p>动态降 \\(\\gamma\\) 是控制尾延迟的手段，但其滞后是新的失败模式。连续拒绝率超阈值才降 \\(\\gamma\\)，意味着在分布漂移（例如对话从短视觉问答切到多图推理）发生后的若干步内，系统仍在用高 \\(\\gamma\\) 做无效并行前向，浪费目标模型算力，尾延迟在这段窗口内被拉长。更细的做法是把降 \\(\\gamma\\) 的判据从\"连续拒绝计数\"改成对 \\(\\alpha\\) 的在线估计——用最近若干步的接受长度做指数滑动平均，阈值触及时立即降 \\(\\gamma\\)，恢复时缓慢升，避免在漂移边界上震荡。</p>\n<p>具体例子：一个多模态 agent 会话，前半段是单图问答（\\(\\alpha\\) 高，\\(\\gamma=8\\) 划算），后半段切到多图对比（视觉上下文变长，草稿注意力稀释，\\(\\alpha\\) 回落）。若降 \\(\\gamma\\) 滞后，后半段每个解码步都在做 9 位置验证却只提交一两个 token，P99 延迟显著高于纯自回归；此时正确的工程动作是按模态动态调 \\(\\gamma\\)，而不是继续押注高 \\(\\gamma\\)。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-39\">三十九 · 规模上去以后哪里先崩</h3>\n<p>把五个维度按规模排序，崩溃顺序是可以判断的。最先崩的是显存：草稿模型的常驻权重在单卡上是硬约束，batch size 与草稿二选一，高并发下草稿被换出使投机静默失效——这是容量问题，发生在并发爬升的早期。其次是尾延迟：\\(\\gamma\\) 偏大加上动态调整滞后，在负载模态切换时把 P99 拉高，表现为 SLO 违约而非吞吐下降。第三是通信：分离式拓扑下视觉 KV 的搬运量随请求数线性增长，预填到解码的链路先饱和。第四是带宽：长视觉上下文使验证前向的固定 KV 读取成本抬高，\\(\\alpha\\) 同时回落，加速比趋近 1。最后才是功耗：机架级功率尖峰在 \\(\\gamma\\) 与 batch 都被推到上限时才成为约束，且它通过降频反向作用于前四项。</p>\n<p>这个顺序给出的工程判断是：跨阶段视觉投机的容量规划应以\"草稿权重 + 视觉 KV 常驻\"为第一约束反推 batch，而不是先定 batch 再塞草稿；\\(\\gamma\\) 的控制应以在线 \\(\\alpha\\) 估计为主、拒绝计数为辅，把滞后窗口压到最短；分离式部署应把草稿放在解码侧、视觉 KV 只传一次并只读复用，避免草稿与目标之间的 KV 同步。规模继续上升时，真正的拐点不在单卡算力，而在\"草稿模型是否还值得常驻\"——当并发足够高、解码阶段在端到端时间中的占比被预填与传输压缩到某个阈值以下，去掉草稿、退回纯自回归加连续批处理，反而是尾延迟更稳的选择。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-40\">四十 · 规模上去以后，先崩的是显存，不是算力</h3>\n<p>把视觉投机解码放进 NVL72 的在线服务里，最先触顶的约束不是目标模型的 MMA 吞吐，而是草稿模型与 batch size 之间的零和博弈。草稿模型要常驻一份权重、一份独立的分页 KV 池，还要在每步读取视觉 KV 摘要向量；视觉 KV 本身在预填后标为只读、验证阶段复用不重算，这部分不涨，但草稿侧的文本 KV 随 γ 与并发线性增长。单卡显存预算固定时，容量规划退化为一个显式取舍：给定权重占用 $M_w$、每请求 KV 占用 $M_{kv}$、草稿额外开销 $M_d$，可承载并发为 $B \\approx \\lfloor (M_{\\text{card}} - M_w - M_d)/M_{kv} \\rfloor$。$M_d$ 一旦把 $B$ 压到调度器无法填满 SM，投机带来的 1.8–2.4 倍解码吞吐就被并发损失吃掉；高并发下草稿模型被换出，投机直接失效，退化为纯自回归。</p>\n<p>第二个崩点是接受率随视觉上下文长度衰减。公式 $\\text{加速比} \\approx \\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)(\\gamma c+1)}$ 里，$\\alpha$ 是逐位置接受率的期望，$c$ 是草稿单步相对目标单步的代价比。视觉问答下 $\\alpha$ 从通用草稿的 0.5–0.6 抬到 0.75–0.85，收益成立；但视频或多图输入把视觉 token 拉长后，草稿模型的跨模态注意力被稀释，$\\alpha$ 回落到接近通用草稿水平，而 $\\gamma c+1$ 里的验证开销一分不少——分子趋近于 1、分母仍大于 1，加速比趋近甚至低于 1。此时系统在“做了并行前向却没换来接受长度”的状态下空转，目标模型算力被无效验证占用，尾延迟反而变差。</p>\n<p>第三个崩点是动态降 γ 的滞后。连续拒绝率超阈值触发降 γ 是正确方向，但阈值判定基于滑动窗口，分布漂移（例如 agent 从图像问答切到长文档配图推理）发生时窗口尚未反映，系统会继续以 γ=4–8 发起并行前向。伪代码上应把判定前移：<span>若首个拒绝位置 $i^\\*$ 的 $p/q$ 比值连续两步低于阈值，则本批次立即把 γ 减半，并把视觉 KV 摘要向量标记为需重算</span>，而不是等窗口统计。工程判断是：视觉投机的容量上限由草稿显存决定，收益上限由 $\\alpha$ 与视觉上下文长度共同决定；短视觉上下文、草稿与目标分布接近的场景才值得开，长视频多图场景应默认关闭或降到 γ=2，把省下的显存还给 batch。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先触发的约束</th><th>系统表现</th></tr></thead><tbody><tr><td>并发上升</td><td>草稿模型显存挤压 batch</td><td>SM 填充不足，吞吐回落</td></tr><tr><td>视觉上下文变长</td><td>接受率 $\\alpha$ 衰减</td><td>验证开销在、加速比消失</td></tr><tr><td>分布漂移</td><td>降 γ 判定滞后</td><td>无效并行前向，尾延迟抬升</td></tr></tbody></table>\n<h3 id=\"alg-cross-stage-vis-spec-sec-41\">四十一 · 精度漂移：接受率是分布距离的代理指标</h3>\n<p>跨阶段视觉投机解码的“精度问题”不是数值溢出，而是草稿分布与目标分布之间的统计距离在运行中漂移。核心判据是接受长度 \\(L_{acc} = \\min\\{i : u_i &gt; p_i/q_i\\}\\)，其中 \\(p_i\\) 为目标分布、\\(q_i\\) 为草稿分布、\\(u_i\\) 为均匀采样。工程上不直接观测 \\(p_i/q_i\\)，而是用逐位置接受率的滑动窗口作为代理：对每个 batch 记录被接受前缀长度与 γ 的比值，得到 \\(\\hat{\\alpha}\\)。视觉问答场景下 \\(\\hat{\\alpha}\\) 应稳定在 0.75–0.85；一旦窗口均值跌破 0.65 并持续若干窗口，说明视觉条件已不能有效约束草稿，等价于退回通用草稿的 0.5–0.6 区间。此时吞吐增益公式 \\(\\text{加速比} \\approx \\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)(\\gamma c+1)}\\) 中的 \\(\\alpha\\) 塌陷，而验证阶段的目标模型并行前向开销 \\(c\\) 不变，净收益迅速转负。</p>\n<p>精度漂移的典型来源有三类：其一，图像分辨率或长宽比在请求间跳变，ViT 编码输出的视觉 KV 分布与草稿模型训练时的条件分布错位；其二，多轮 agent 会话中文本上下文增长，草稿模型读取的视觉 KV 摘要向量被文本注意力稀释；其三，目标模型侧做了量化（如 FP8/NVFP4）而草稿模型保持高精度，两者分布差被放大。诊断手段是分桶统计：按视觉 token 数、按模态（单图/多图/视频帧）、按会话轮次分别记录 \\(\\hat{\\alpha}\\)，定位是哪一桶在拖低全局值。回滚策略是分级降级——先把 γ 从 8 降到 4，若 \\(\\hat{\\alpha}\\) 仍低于阈值则关闭投机、退回纯自回归解码，同时把该请求标记为“视觉条件失效”写入路由元数据，供后续调度避开。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-42\">四十二 · OOM 与显存挤压：草稿模型是容量约束的主项</h3>\n<p>草稿模型额外占用显存，在 NVL72 单卡上表现为 batch size 与草稿模型二选一。视觉 KV 写入分页池并标记只读，这部分是共享的、不随投机开关变化；真正挤压容量的是草稿模型的权重、其独立的 KV 分页池以及 γ 个候选 token 的并行 logits 缓冲。高并发时若显存水位逼近上限，调度器会把草稿模型换出到主机内存，下一次请求触发换入，投机路径实际失效但请求仍按投机模式排队，形成“名义投机、实际自回归”的隐性退化。监控上要区分两个指标：草稿模型驻留率（resident ratio）与投机实际生效率（accepted-prefix 非空的比例）。前者掉、后者跟着掉，就是换出导致的假投机。</p>\n<p>容量规划的做法是把草稿模型显存视为固定开销，先扣减再算 batch：设单卡可用显存 \\(M\\)，目标模型权重与视觉 KV 池占 \\(M_{tgt}\\)，草稿模型占 \\(M_{d}\\)，则可用于文本 KV 的余量为 \\(M - M_{tgt} - M_{d}\\)，batch size 由该余量除以每序列 KV 增量决定。当 \\(M_d\\) 占比过高时，正确动作不是硬撑 batch，而是降低 γ 以减少候选缓冲，或对草稿模型做更激进的量化。回滚路径是显式开关：显存水位超过阈值即把草稿模型标记为不可用，请求走纯自回归，避免换入换出的抖动。视频或多图长视觉上下文会同时抬高视觉 KV 池与草稿注意力开销，这类请求应在路由层就打上“低投机优先级”标签。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-43\">四十三 · 批抖动：γ 动态调整与批组成变化的耦合</h3>\n<p>连续拒绝率超阈值时动态降 γ 是既定稳定性技巧，但滞后会在分布漂移时持续做无效并行前向，浪费目标模型算力。批抖动来自两个方向：一是同一 batch 内不同请求的 \\(\\hat{\\alpha}\\) 差异大，短视觉上下文请求接受率高、长视频请求接受率低，统一 γ 让高接受率请求被低接受率请求拖累；二是 γ 切换本身改变每步的计算图与显存占用，触发批重组，重组期间 GPU 利用率出现凹口。诊断批抖动要看每步的有效 token 产出（accepted tokens per step）与步间方差的比值，方差突增说明批内异质性上升。</p>\n<p>缓解机制是按请求维护独立的 γ 状态机，而非按 batch 统一：每个请求记录最近若干步的接受前缀长度，用指数滑动平均估计 \\(\\hat{\\alpha}_i\\)，当 \\(\\hat{\\alpha}_i\\) 低于阈值时对该请求单独降 γ，调度器在组批时把 γ 相同的请求聚到一起，减少计算图切换。伪代码思路是：对请求 \\(i\\)，若 \\(\\hat{\\alpha}_i &lt; \\alpha_{low}\\) 则 \\(\\gamma_i \\leftarrow \\max(4, \\gamma_i - 1)\\)，若 \\(\\hat{\\alpha}_i &gt; \\alpha_{high}\\) 则 \\(\\gamma_i \\leftarrow \\min(8, \\gamma_i + 1)\\)，且每 \\(k\\) 步才允许一次调整以抑制振荡。代价是调度器需要维护每请求状态并做 γ 感知的组批，增加 CPU 侧开销；收益是尾延迟方差收敛。回滚是把 γ 状态机整体冻结到保守值 4，牺牲峰值吞吐换稳定。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-44\">四十四 · 路由不均与尾延迟尖刺</h3>\n<p>视觉上下文长度是路由不均的根源。短视觉上下文的请求接受率高、解码快，长视频或多图请求接受率回落到接近通用草稿水平，加速比消失而验证开销仍在——这类请求在共享队列里会持续占用目标模型算力却产出低，形成尾延迟尖刺。监控要按视觉 token 数分位数看 P99 解码时延，并与 \\(\\hat{\\alpha}\\) 分桶对齐：若 P99 请求集中在长视觉桶且该桶 \\(\\hat{\\alpha}\\) 低于 0.6，则尖刺由投机失效引起，而非单纯的负载峰值。</p>\n<p>路由层的机制是按模态与视觉长度做投机准入：视觉 token 数超过阈值的请求默认关闭投机或强制 γ=4，短上下文请求走 γ=8 的快路径。分离式预填/解码部署下，预填节点完成 ViT 编码与跨模态注意力后，把视觉 KV 摘要向量与“建议 γ”一并写入请求元数据传给解码节点，解码节点据此直接选路，避免在解码侧重新探测。代价是预填节点多一次元数据计算与传递，延迟增加在预填阶段可被批处理摊薄；收益是解码侧尾延迟可控。回滚是全局关闭按模态路由，所有请求统一 γ=4，把尖刺转化为均匀的吞吐下降。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-45\">四十五 · 监控面与回滚闸门</h3>\n<p>需要一组最小监控面把上述失败模式串起来：逐位置接受率 \\(\\hat{\\alpha}\\)（按模态、视觉长度、会话轮次分桶）、草稿模型驻留率、投机实际生效率、每步有效 token 产出及其步间方差、P99 解码时延与视觉 token 数的联合分布、目标模型验证前向的算力占用。这些指标共同回答一个问题：当前吞吐是来自真实接受还是来自无效并行前向。判据是“有效 token 产出 / 目标模型前向次数”，该比值随 \\(\\hat{\\alpha}\\) 单调，比值下降即投机在空转。</p>\n<p>回滚闸门分三级，按自动化程度递进：一级是 γ 降档，由每请求状态机自动执行；二级是投机开关，当分桶 \\(\\hat{\\alpha}\\) 跌破阈值或草稿驻留率跌破阈值时对该桶关闭投机；三级是全局回退，当显存水位或 P99 时延越过硬阈值时整个服务退回纯自回归，并冻结路由元数据中的投机建议。闸门必须带滞回区间，避免在阈值附近反复切换造成批重组抖动。工程判断是：跨阶段视觉投机的收益高度依赖视觉上下文长度分布，部署前应先离线统计目标负载的视觉 token 数分布，若长上下文占比高，投机的期望收益本就有限，闸门阈值应设得更保守，把容量留给 batch size 而非草稿模型。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-46\">四十六 · 失效链的定位：从接受率塌陷到显存挤压</h3>\n<p>跨阶段视觉投机的收益完全建立在接受率 α 上，因此诊断的第一入口不是端到端延迟，而是按模态分桶的 α 时间序列。工程上把 α 拆成三个可观测分量：草稿模型对视觉 KV 摘要向量的读取命中率、逐位置 p/q 比值的分布、以及连续拒绝游程长度。当视频帧数或多图数量上升时，草稿模型的跨模态注意力被稀释，α 从 0.75–0.85 回落到接近通用草稿的 0.5–0.6 区间，此时加速比公式给出的是负收益判断：验证阶段仍要对 γ 个候选做一次目标模型并行前向，视觉 KV 复用省掉了编码开销，但目标模型的算力已被无效候选占满。监控上应对 α 设两条线——软阈值触发降 γ，硬阈值直接切回非投机路径，避免在分布漂移时持续做无效并行前向。降 γ 的滞后是典型故障：调度器按批统计 α，而批内样本模态混杂，长视觉上下文样本拉低均值后，短上下文样本被连带降 γ，吞吐反而下降。正确做法是按请求的视觉 token 数分桶统计，桶内独立决策 γ。</p>\n<p>第二类失效是容量侧的硬约束。草稿模型与目标模型共享视觉 KV，验证阶段无额外视觉编码开销，但草稿模型自身权重与激活仍要占显存，在 NVL72 单卡上直接与 batch size 争夺同一块 HBM。高并发时若调度器为保 batch 把草稿模型换出到主机侧，投机路径退化为串行草稿生成再验证，延迟尖刺立刻出现；若保草稿模型则 batch 被压小，吞吐掉到非投机水平以下。这是一个二选一，不存在中间态。诊断信号是草稿模型驻留状态与 batch size 的联合曲线：一旦出现“草稿驻留但 batch 低于阈值”或“batch 达标但草稿被换出”的组合，就应判定为容量失配而非算法失效。缓解手段是给草稿模型设显存配额上限，并在配额内限制并发投机请求数，让排队发生在准入层而不是换出层。</p>\n<p>第三类是批抖动与路由不均。视觉问答请求的视觉 token 长度方差大，分页池中只读视觉 KV 块的碎片化会放大这种方差：短请求快速释放块，长请求持续占用大块，批内 token 数在连续批处理中剧烈波动，导致目标模型前向的填充率忽高忽低。路由层面，若按请求数而非按视觉 token 数做负载均衡，某些副本会堆积长上下文请求，其 α 偏低、γ 被降、单请求延迟拉长，形成尾延迟尖刺。可用的判据是把每副本的“有效接受 token 数 / 目标模型前向次数”作为路由权重，低于全局均值的副本降权，而不是等尾延迟越过 SLO 再补救。回滚策略应分级：一级只降 γ 并保留视觉 KV 复用；二级关闭投机、走纯自回归但保留分页池中的只读视觉块；三级把长视觉上下文请求整体迁到专用副本池，避免污染短上下文批。</p>\n<p>精度问题在这套方案里表现为接受前缀 KV 与重采样位置的拼接一致性。接受 token 的 KV 直接写入、拒绝位置由目标模型重采样，若草稿模型与目标模型的数值精度路径不同（例如草稿走低精度、目标走另一档），p/q 比值在长序列上会漂移，表现为 α 缓慢下滑而非突降，容易被误判为模态稀释。诊断方法是固定一批短视觉上下文请求做回归探针，若其 α 也同步下滑，则指向数值路径而非视觉注意力稀释。下表给出失效模式与首要观测量的对应关系，用于值班时的快速分诊。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>首要观测量</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>长视觉上下文稀释</td><td>按视觉 token 分桶的 α</td><td>目标模型算力被无效候选占用</td><td>按模态降 γ，硬阈值切非投机</td></tr><tr><td>草稿模型换出</td><td>草稿驻留状态 × batch size</td><td>延迟尖刺、吞吐跌破非投机基线</td><td>显存配额 + 准入限流</td></tr><tr><td>批抖动</td><td>批内 token 方差、填充率</td><td>前向利用率下降</td><td>按视觉 token 数路由</td></tr><tr><td>数值漂移</td><td>固定探针集的 α 趋势</td><td>接受率缓降、验证开销不变</td><td>对齐草稿与目标精度路径</td></tr></tbody></table>\n<h3 id=\"alg-cross-stage-vis-spec-sec-47\">四十七 · 决策轴：把同族算法压到四个可测量维度</h3>\n<p>跨阶段视觉投机解码不是孤立选项，它和视觉缓存复用、预语言模型视觉剪枝、双阶段统一 token 缩减、熵引导视觉剪枝、逐层视觉 token 压缩、多模态全静态量化、量化感知视觉剪枝、跨阶段自适应并行服务、多模态自适应投机解码、ViTCoP、DUET-VLM 处在同一条服务链路上，彼此争夺的是同一批资源：预填算力、解码串行步数、显存容量、跨阶段带宽。选型时不要按“哪个算法更先进”排序，而要把候选压到四个可测量维度上：第一，它削减的是预填的视觉 token 数，还是解码的自回归步数；第二，它是否引入额外常驻权重（草稿模型、第二套量化副本）；第三，它对视觉上下文长度的敏感方向（越长越有效，还是越长越失效）；第四，它与目标模型分布的一致性来源（同源视觉编码器、离线校准集、还是运行时统计）。跨阶段视觉投机解码在这四维上的坐标很明确：削减解码步数、引入一份草稿权重、对视觉上下文长度负敏感、一致性来自共享视觉编码器输出。任何与它竞争的方案，只要在这四维上有一维明显更优且不牺牲其余三维，就应当被优先考虑。</p>\n<p>把四维写成可比较的量：设候选算法带来的解码步数缩减为 <span class=\"formula\">$$S \\approx \\frac{1-\\alpha^{\\gamma+1}}{(1-\\alpha)(\\gamma c+1)}$$</span>，其中 α 为接受率、γ 为草稿步数、c 为草稿单步相对目标单步的代价比。这个式子的工程含义是：当 α 落在 0.5–0.6（通用草稿在视觉问答上的水平），即使 γ 取 8，分母中的 γc 项也会把增益压到接近 1；只有当 α 抬到 0.75–0.85，分子才真正拉开。因此“是否值得上投机”的第一个判据不是 γ 能开多大，而是能否把 α 稳定抬过 0.7。跨阶段视觉投机的全部价值就押在这一步上：用视觉编码器输出作为草稿的跨模态条件，把 α 从 0.5–0.6 抬到 0.75–0.85，端到端解码吞吐因此提升 1.8–2.4 倍。反过来，任何让 α 回落的负载特征，都会让这个算法退化成“多花一份显存买不到吞吐”。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-48\">四十八 · 与剪枝/压缩族的对照：削减对象不同，代价位置不同</h3>\n<p>预语言模型视觉剪枝、熵引导视觉剪枝、逐层视觉 token 压缩、双阶段统一 token 缩减，削减的都是进入语言模型的视觉 token 数量，收益体现在预填阶段的注意力和 FFN 计算量上，同时顺带降低视觉 KV 的常驻显存。它们的代价位置在预填：剪枝比例越高，视觉信息损失越大，且损失不可在解码阶段恢复。跨阶段视觉投机削减的是解码步数，预填阶段几乎不变（视觉 KV 照常写入分页池并标记只读），代价位置在显存容量——草稿模型常驻。这两族不是替代关系而是串联关系：剪枝把视觉 token 从 N 压到 N'，投机再把解码步数从 T 压到 T/S。串联时的关键判断是顺序效应：剪枝越激进，草稿模型读到的视觉 KV 摘要向量信息越少，α 越容易回落；因此高剪枝比例 + 高 γ 的组合是危险的，正确做法是剪枝比例上升时同步下调 γ，而不是两边都拉满。</p>\n<p>具体例子：一个多模态 agent 服务在 8K 视觉上下文、batch 较大的配置下，若采用逐层视觉 token 压缩把视觉 token 压到原来的三分之一，预填延迟显著下降，但草稿模型可读的视觉条件被稀释，α 从 0.8 区间滑向 0.6 附近，此时 γ=8 的并行前向仍在做，验证开销照付而接受前缀变短，端到端反而变差。诊断信号是“接受长度 L_acc 的均值下降但 γ 未变”，处理动作是把 γ 降到 4 并复核剪枝比例。这条经验可以固化成选型规则：剪枝族与投机族同时启用时，γ 必须作为剪枝比例的因变量，而不是独立超参。</p>\n<table class=\"mini\"><thead><tr><th>对照族</th><th>削减对象</th><th>主要代价位置</th><th>与跨阶段视觉投机的组合判断</th></tr></thead><tbody><tr><td>预语言模型视觉剪枝 / 熵引导剪枝</td><td>进入 LLM 的视觉 token 数</td><td>预填算力、视觉信息损失</td><td>可串联，但剪枝比例上升须下调 γ</td></tr><tr><td>逐层视觉 token 压缩 / 双阶段统一缩减</td><td>视觉 token 数与层间冗余</td><td>预填算力、跨层带宽</td><td>串联后 α 易回落，需重测接受率再定 γ</td></tr><tr><td>多模态全静态量化 / 量化感知视觉剪枝</td><td>权重与激活位宽</td><td>显存带宽、数值精度</td><td>与草稿模型叠加时显存更紧，优先保 batch</td></tr><tr><td>视觉缓存复用</td><td>重复预填的视觉编码</td><td>预填算力（跨请求）</td><td>与投机共享只读视觉 KV，天然互补</td></tr></tbody></table>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-49\">四十九 · 与并行/调度族的对照：谁在争 batch size</h3>\n<p>跨阶段自适应并行服务、ViTCoP 视觉文本协同预填、DUET-VLM 双阶段 token 缩减，处理的是阶段间的资源分配与预填-解码的重叠方式，它们的目标是让预填与解码在同一时间片上互不空等。跨阶段视觉投机与它们的关系是“占用同一块显存预算的竞争者”。草稿模型额外占用显存，在 NVL72 单卡上直接表现为 batch size 与草稿模型的二选一：高并发时若草稿模型被换出，投机路径整体失效，退化为纯目标模型解码，而此时调度器仍按“有投机”的假设分配 SLO 预算，造成实际延迟超预期。这是选型时最容易被忽略的一条：并行/调度族的收益是连续的、与并发度同向；投机族的收益是离散的、依赖草稿模型常驻。两者叠加时，必须把草稿模型的显存占用从可用 batch 预算中先扣除，再谈并行策略。</p>\n<p>ViTCoP 的协同预填把视觉与文本的预填融合，减少阶段切换的空泡；跨阶段视觉投机则在预填完成后接管解码。二者串联的收益是叠加的，但有一个共享前提：视觉 KV 必须一次写入、多次只读复用。跨阶段视觉投机的验证阶段复用视觉 KV 不重算，ViTCoP 的协同预填也依赖同一份视觉 KV 不被重复编码，因此两者在“视觉 KV 只读标记”这一机制上是同源的，组合时不需要额外的一致性协议。DUET-VLM 的双阶段缩减若在预填后改变了视觉 KV 的形状，则会破坏这个前提，此时要么放弃缩减、要么在缩减后重建草稿模型的视觉条件摘要，代价是一次额外的摘要投影前向。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-50\">五十 · 与投机族内部的对照：通用投机 vs 自适应投机 vs 跨阶段视觉投机</h3>\n<p>通用投机解码与多模态自适应投机解码是跨阶段视觉投机的直接同族。三者的差别不在验证协议（都是目标模型一次并行前向、逐位置比对、首个拒绝位置截断、接受前缀 KV 直接写入、拒绝位置重采样），而在草稿条件的来源与 γ 的调度策略。通用投机的草稿只看文本，对图像内容不敏感，视觉问答上 α 只有 0.5–0.6，加速比有限；多模态自适应投机在 γ 上做运行时调整，但草稿条件仍不必然绑定视觉编码器；跨阶段视觉投机把视觉编码器输出作为跨模态条件，α 抬到 0.75–0.85。选型判据因此非常直接：若负载以纯文本为主、视觉输入稀疏，通用投机的显存代价最小，是默认选项；若视觉问答占比高且视觉上下文短，跨阶段视觉投机的 α 优势能兑现为 1.8–2.4 倍吞吐；若负载在长短视觉上下文之间剧烈波动，自适应投机的 γ 调度是必要的补丁，但必须与跨阶段视觉条件同时存在，否则 γ 调得再准也救不回被稀释的 α。</p>\n<p>三者的失败模式也各不相同，诊断时应按症状反查算法。通用投机的典型症状是 α 长期贴在 0.5–0.6、γ 增大无效；跨阶段视觉投机的典型症状是长视频或多图下 α 回落到接近通用草稿水平，加速比消失而验证开销仍在——此时正确的动作是按模态动态调 γ，而不是加大草稿模型；自适应投机的典型症状是连续拒绝率超阈值后动态降 γ 滞后，在分布漂移时持续做无效并行前向，浪费目标模型算力。把这三条症状写进监控面板，比在选型阶段争论算法优劣更有效，因为同一服务在不同时段可能落在不同症状上。</p>\n<div class=\"formula\">$$L_{acc} = \\min\\{i : u_i &gt; p_i/q_i\\}$$</div>\n<p>这条接受长度定义是三族共用的，也是诊断的抓手：L_acc 的分布若出现长尾截断（大量样本在 i=1 或 2 就拒绝），说明草稿与目标分布在该负载上已经脱钩，任何 γ 调整都是徒劳，应退回非投机路径并检查视觉条件是否被稀释。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-51\">五十一 · 决策表：按负载形态给出选择与适用条件</h3>\n<p>把上述对照收敛成一张可执行的决策表。表的每一行对应一种可观测的负载形态，列给出首选算法、必须同时满足的适用条件、以及一旦条件破坏时的回退动作。表中不写具体批大小与 SLO 数值，因为这些量随部署拓扑变化，只保留方向性判断。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>首选</th><th>适用条件</th><th>条件破坏时的回退</th></tr></thead><tbody><tr><td>短视觉上下文、视觉问答为主、并发中等</td><td>跨阶段视觉投机，γ=4–8</td><td>草稿模型可常驻、视觉 KV 只读复用、α 稳定在 0.75–0.85</td><td>α 跌破 0.7 则降 γ 至 4，再跌破则关投机</td></tr><tr><td>长视频或多图、视觉上下文极长</td><td>剪枝/压缩族优先，投机仅作可选</td><td>剪枝比例受控、草稿注意力未被稀释</td><td>α 回落至通用水平则关投机，保留剪枝</td></tr><tr><td>高并发、显存吃紧</td><td>视觉缓存复用 + 并行调度，暂缓投机</td><td>草稿模型不挤占 batch 预算</td><td>草稿被换出即视为投机失效，按纯目标模型重排 SLO</td></tr><tr><td>纯文本为主、视觉稀疏</td><td>通用投机解码</td><td>草稿显存代价可接受</td><td>α 无提升则退回非投机</td></tr><tr><td>负载形态剧烈波动</td><td>跨阶段视觉投机 + 自适应 γ</td><td>拒绝率阈值触发降 γ 的滞后可控</td><td>滞后明显则改为按模态预置 γ 档位</td></tr></tbody></table>\n<p>读表时要抓住两条硬约束。第一条是显存：草稿模型额外占用显存，NVL72 单卡需在 batch size 与草稿模型间权衡，这是跨阶段视觉投机的主要容量约束，也是它在高并发场景下让位于缓存复用与调度族的原因。第二条是视觉上下文长度：适用边界明确为视觉上下文较短、草稿与目标分布接近的场景，长视频或多图下收益衰减。两条约束共同决定了这张表不是“谁更好”的排名，而是“在什么条件下谁的收益能兑现”的分区。</p>\n\n<h3 id=\"alg-cross-stage-vis-spec-sec-52\">五十二 · 工程判断：把选型固化成运行时开关而非静态配置</h3>\n<p>决策表若只停留在部署文档里，价值有限，因为负载形态会在同一服务的生命周期内漂移。可行的做法是把选型固化成运行时开关，用三个观测量驱动：接受长度 L_acc 的滑动均值、连续拒绝率的超阈值计数、以及草稿模型是否因显存压力被换出。三个量分别对应 α 的退化、γ 调度的滞后、以及容量约束的触发。开关的动作集合很小：降 γ、关投机、切回纯目标模型解码、或把视觉条件摘要重建一次。这套开关的成本极低，因为验证阶段的视觉 KV 本就复用不重算，切换路径不需要重新编码视觉输入。</p>\n<p>一个具体的工程判断落在 γ 的档位设计上：不要给 γ 一个连续可调的范围，而是给 4 和 8 两个档位，中间不设插值。理由是公式中 γc 项对吞吐的边际贡献在 α 高时为正、在 α 低时为负，而 α 的估计本身有噪声，连续调节会把噪声放大成振荡。两档设计让每次切换都有明确的滞回区间：α 高于上界升到 8，低于下界降到 4，中间保持当前档位。这与“连续拒绝率超阈值则动态降 γ”的机制一致，但把滞后问题从“调参”变成“设计滞回”，从而避免在分布漂移时持续做无效并行前向、浪费目标模型算力。最终，跨阶段视觉投机是否启用，不取决于它在论文坐标里的位置，而取决于这条服务链路上草稿模型能否常驻、视觉上下文是否够短、以及 α 能否被稳定观测——三者任一不成立，就该让位给剪枝、缓存复用或纯调度族。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · 跨模态对齐与蒸馏压缩</td></tr><tr><td>解决什么</td><td>多模态agent服务中解码阶段自回归逐token生成，视觉token已固定但文本生成仍是串行瓶颈；通用投机解码草稿模型…</td></tr><tr><td>一句话机制</td><td>用同一VLM的视觉编码器输出作为草稿模型的跨模态条件，草稿模型以视觉token+已生成文本为输入并行提出γ个候选，目标…</td></tr><tr><td>代价与失效</td><td>草稿模型额外占用显存，NVL72单卡需在batch size与草稿模型间权衡；视频或多图长视觉上下文下草稿模型注意力被稀释，接受率回落，需…</td></tr><tr><td>后继</td><td>DUET-VLM 双阶段 token 缩减</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-cross-stage-vis-spec · 共 8 个片段</p>\n";break;}}})();
